const guideDepth = {"first-period": {"understand": ["The first cycles may take time to settle. Bleeding can look red, pink or brown. One person’s pattern is not a target for everyone.", "قد تحتاج الدورات الأولى وقتًا لتنتظم. قد يكون الدم أحمر أو ورديًا أو بنيًا. نمط دورة شخص آخر ليس معيارًا للجميع."], "assessment": ["Discuss bleeding that disrupts school, dizziness, or troublesome pain. Bring your dates and explain what you cannot do during your period.", "ناقشي النزف الذي يعطل المدرسة أو الدوخة أو الألم المزعج. أحضري التواريخ واشرحي الأنشطة التي يمنعك منها الحيض."], "options": ["Choose a comfortable product and follow its changing and cleaning instructions. Ask a trusted adult for supplies and practical help.", "اختاري وسيلة مريحة واتّبعي تعليمات تغييرها وتنظيفها. اطلبي من بالغ موثوق المساعدة العملية وتوفير المستلزمات."], "faq": [["Must my period arrive on the same date each month?", "هل يجب أن تأتي الدورة في التاريخ نفسه كل شهر؟", "No. Record the interval between first bleeding days rather than expecting a fixed calendar date.", "لا. دوّني الفاصل بين أول يوم للنزف في الدورتين بدل انتظار تاريخ ثابت."]], "questions": [["Which changes in my bleeding or pain should I report?", "ما تغيّرات النزف أو الألم التي ينبغي إبلاغكم بها؟"], ["How can I manage my period comfortably at school?", "كيف أتعامل مع الدورة براحة في المدرسة؟"]], "related": ["period-pain", "heavy-periods", "missed-periods"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["The first cycles may take time to settle. Bleeding can look red, pink or brown. One person’s pattern is not a target for everyone.", "قد تحتاج الدورات الأولى وقتًا لتنتظم. قد يكون الدم أحمر أو ورديًا أو بنيًا. نمط دورة شخص آخر ليس معيارًا للجميع."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Discuss bleeding that disrupts school, dizziness, or troublesome pain. Bring your dates and explain what you cannot do during your period.", "ناقشي النزف الذي يعطل المدرسة أو الدوخة أو الألم المزعج. أحضري التواريخ واشرحي الأنشطة التي يمنعك منها الحيض."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Choose a comfortable product and follow its changing and cleaning instructions. Ask a trusted adult for supplies and practical help.", "اختاري وسيلة مريحة واتّبعي تعليمات تغييرها وتنظيفها. اطلبي من بالغ موثوق المساعدة العملية وتوفير المستلزمات."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Prepare a small kit with period products and spare underwear. Follow the product instructions, and choose what feels comfortable. If your first period starts at school, a trusted teacher or nurse can help. You do not need to keep worries about bleeding or pain to yourself.", "جهّزي حقيبة صغيرة بمنتجات الدورة وملابس داخلية إضافية. اتبعي تعليمات المنتج واختاري ما يريحك. إذا بدأت الدورة في المدرسة يمكن لمعلمة موثوقة أو ممرضة مساعدتك. لا تحتاجين كتمان القلق من النزف أو الألم."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Note dates and how you feel rather than expecting every month to be identical. Ask for assessment if periods have not started by 15, or by 13 without other signs of puberty. Bring questions about products, privacy and pain; no question is embarrassing.", "دوّني التواريخ وشعورك بدل توقع تشابه كل الأشهر. اطلبي تقييمًا إذا لم تبدأ الدورة بعمر ١٥، أو بعمر ١٣ دون علامات بلوغ أخرى. أحضري أسئلتك عن المنتجات والخصوصية والألم؛ لا يوجد سؤال محرج."]}]}, "period-pain": {"understand": ["Womb contractions can cause cramps. Endometriosis, adenomyosis, fibroids or infection can also cause pain. New pain or pain outside periods needs discussion.", "قد تسبب تقلصات الرحم المغص. وقد يحدث الألم مع بطانة الرحم المهاجرة أو العضال الغدي أو الأورام الليفية أو العدوى. ناقشي الألم الجديد أو خارج الدورة."], "assessment": ["A clinician may ask about bleeding, bowel or bladder symptoms and pain during sex. Examination or ultrasound may be offered.", "قد يسأل المختص عن النزف وأعراض الأمعاء والمثانة والألم أثناء الجماع، وقد يقترح فحصًا أو تصويرًا بالموجات الصوتية."], "options": ["Warmth and gentle activity may help. Discuss suitable pain relief, hormonal options or specialist referral if symptoms continue.", "قد يفيد الدفء والنشاط الخفيف. ناقشي المسكن المناسب أو الخيارات الهرمونية أو الإحالة لمختص إذا استمرت الأعراض."], "faq": [["Should I accept pain that stops daily activities?", "هل أقبل ألمًا يعطّل حياتي؟", "No. Its effect on your life is a reason to seek assessment.", "لا. تأثير الألم في حياتك سبب لطلب التقييم."]], "questions": [["What could explain pain between periods?", "ما الذي قد يفسّر الألم بين الدورات؟"], ["When should we reassess if treatment does not help?", "متى نعيد التقييم إن لم يفد العلاج؟"]], "related": ["endometriosis", "fibroids", "pain-sex"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Womb contractions can cause cramps. Endometriosis, adenomyosis, fibroids or infection can also cause pain. New pain or pain outside periods needs discussion.", "قد تسبب تقلصات الرحم المغص. وقد يحدث الألم مع بطانة الرحم المهاجرة أو العضال الغدي أو الأورام الليفية أو العدوى. ناقشي الألم الجديد أو خارج الدورة."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["A clinician may ask about bleeding, bowel or bladder symptoms and pain during sex. Examination or ultrasound may be offered.", "قد يسأل المختص عن النزف وأعراض الأمعاء والمثانة والألم أثناء الجماع، وقد يقترح فحصًا أو تصويرًا بالموجات الصوتية."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Warmth and gentle activity may help. Discuss suitable pain relief, hormonal options or specialist referral if symptoms continue.", "قد يفيد الدفء والنشاط الخفيف. ناقشي المسكن المناسب أو الخيارات الهرمونية أو الإحالة لمختص إذا استمرت الأعراض."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["For familiar cramps, a warm bath, a wrapped heat pack or gentle movement may help. Ask a pharmacist which pain medicine fits your medical history. Do not repeatedly mask severe or worsening pain. Record whether pain prevents sleep, school, work or usual activities.", "للتقلصات المعتادة قد يفيد حمام دافئ أو كمادة مغلفة أو حركة لطيفة. اسألي الصيدلي عن المسكن الملائم لتاريخك الطبي. لا تكتفي بإخفاء الألم الشديد أو المتفاقم. دوّني تأثيره على النوم والدراسة والعمل والنشاط."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If the first approach is not helping, ask what the next assessment or treatment step is. Mention pain between periods, with sex or when using the toilet. These details can change the assessment. Agree when to review the response rather than simply repeating prescriptions.", "إذا لم يفد النهج الأول، اسألي عن خطوة التقييم أو العلاج التالية. اذكري الألم بين الدورات أو مع الجماع أو استخدام المرحاض؛ قد تغيّر هذه التفاصيل التقييم. اتفقي على موعد مراجعة الاستجابة بدل تكرار الوصفات فقط."]}]}, "heavy-periods": {"understand": ["Long bleeding, flooding, frequent product changes and fatigue can indicate a problem. Fibroids, hormonal changes, medicines or bleeding disorders may contribute.", "قد يشير طول النزف وغزارته وكثرة تغيير المستلزمات والتعب إلى مشكلة. وقد تسهم الأورام الليفية أو التغيرات الهرمونية أو الأدوية أو اضطرابات النزف."], "assessment": ["Blood tests may check for anaemia. The pattern of bleeding and associated symptoms guide further tests and specialist referral.", "قد تكشف تحاليل الدم فقر الدم. ويحدد نمط النزف والأعراض المصاحبة الحاجة لفحوصات أخرى أو إحالة للمختص."], "options": ["Choices include medicines that reduce bleeding, hormonal contraception and selected procedures. Explain future pregnancy wishes before discussing procedures.", "تشمل الخيارات أدوية تقلل النزف ووسائل هرمونية وإجراءات مختارة. اذكري رغبتك المستقبلية في الحمل قبل مناقشة الإجراءات."], "faq": [["Do I have to measure blood in millilitres?", "هل يجب قياس الدم بالملليلتر؟", "No. Describe flooding, duration and how bleeding affects your activities.", "لا. صفي شدة النزف ومدته وتأثيره في أنشطتك."]], "questions": [["Should I be tested for anaemia?", "هل أحتاج فحص فقر الدم؟"], ["Which options preserve my future pregnancy choices?", "ما الخيارات التي تحافظ على إمكانية الحمل مستقبلًا؟"]], "related": ["fibroids", "period-pain", "postmenopausal-bleeding"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Long bleeding, flooding, frequent product changes and fatigue can indicate a problem. Fibroids, hormonal changes, medicines or bleeding disorders may contribute.", "قد يشير طول النزف وغزارته وكثرة تغيير المستلزمات والتعب إلى مشكلة. وقد تسهم الأورام الليفية أو التغيرات الهرمونية أو الأدوية أو اضطرابات النزف."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Blood tests may check for anaemia. The pattern of bleeding and associated symptoms guide further tests and specialist referral.", "قد تكشف تحاليل الدم فقر الدم. ويحدد نمط النزف والأعراض المصاحبة الحاجة لفحوصات أخرى أو إحالة للمختص."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Choices include medicines that reduce bleeding, hormonal contraception and selected procedures. Explain future pregnancy wishes before discussing procedures.", "تشمل الخيارات أدوية تقلل النزف ووسائل هرمونية وإجراءات مختارة. اذكري رغبتك المستقبلية في الحمل قبل مناقشة الإجراءات."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Keep a record of leaks, frequent product changes, clots and missed activities. Tell the clinician about tiredness or breathlessness and all medicines, including blood thinners. You do not need an exact blood-volume measurement to ask for help.", "سجّلي التسرب وتكرار تغيير المنتجات والجلطات والأنشطة التي تفوتك. أخبري المختص بالتعب أو ضيق النفس وكل الأدوية بما فيها مميعات الدم. لا تحتاجين قياسًا دقيقًا لكمية الدم لطلب المساعدة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask whether anaemia testing is needed and which treatment fits future pregnancy plans. Medicines, hormonal methods and procedures are different choices. If bleeding continues despite treatment, ask for reassessment and a clear result-review plan. Report bleeding between periods or after sex separately.", "اسألي عن الحاجة لفحص فقر الدم والعلاج الملائم لخطط الحمل. تختلف الأدوية والوسائل الهرمونية والإجراءات. إذا استمر النزف رغم العلاج اطلبي إعادة التقييم وخطة واضحة لمراجعة النتائج. اذكري النزف بين الدورات أو بعد الجماع منفصلًا."]}]}, "missed-periods": {"understand": ["Pregnancy is one possibility. Breastfeeding, contraception, weight changes, intense exercise, thyroid conditions and ovarian hormone conditions can also change periods.", "الحمل أحد الاحتمالات. وقد تغيّر الدورة الرضاعة ومنع الحمل وتغيّرات الوزن والرياضة الشديدة وأمراض الغدة الدرقية واضطرابات هرمونات المبيض."], "assessment": ["Bring cycle dates and medicine details. A clinician may arrange hormone blood tests or further assessment depending on your history.", "أحضري تواريخ الدورة وتفاصيل الأدوية. قد يطلب المختص تحاليل هرمونات أو تقييمًا إضافيًا بحسب تاريخك."], "options": ["Treatment depends on the cause. A prescription used to change bleeding does not by itself explain why periods stopped.", "يعتمد العلاج على السبب. وصف دواء لتغيير النزف لا يفسّر وحده سبب توقف الدورة."], "faq": [["Can the cycle calculator diagnose the cause?", "هل تشخّص حاسبة الدورة السبب؟", "No. It measures dates; it does not assess pregnancy or hormones.", "لا. تقيس الحاسبة التواريخ ولا تقيّم الحمل أو الهرمونات."]], "questions": [["Which possible causes fit my history?", "ما الأسباب المحتملة المناسبة لتاريخي؟"], ["Which tests would change the next step?", "ما الفحوصات التي ستغيّر الخطوة التالية؟"]], "related": ["pcos", "perimenopause", "ectopic"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Pregnancy is one possibility. Breastfeeding, contraception, weight changes, intense exercise, thyroid conditions and ovarian hormone conditions can also change periods.", "الحمل أحد الاحتمالات. وقد تغيّر الدورة الرضاعة ومنع الحمل وتغيّرات الوزن والرياضة الشديدة وأمراض الغدة الدرقية واضطرابات هرمونات المبيض."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Bring cycle dates and medicine details. A clinician may arrange hormone blood tests or further assessment depending on your history.", "أحضري تواريخ الدورة وتفاصيل الأدوية. قد يطلب المختص تحاليل هرمونات أو تقييمًا إضافيًا بحسب تاريخك."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Treatment depends on the cause. A prescription used to change bleeding does not by itself explain why periods stopped.", "يعتمد العلاج على السبب. وصف دواء لتغيير النزف لا يفسّر وحده سبب توقف الدورة."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Write down your last period and recent changes in contraception, breastfeeding, stress, exercise, weight or health. If pregnancy is possible, follow the instructions on a pregnancy test. A late period alone cannot tell you whether the cause is pregnancy, hormones or another condition.", "دوّني آخر دورة والتغيرات في منع الحمل والرضاعة والتوتر والرياضة والوزن والصحة. إذا كان الحمل ممكنًا فاتبعي تعليمات اختبار الحمل. تأخر الدورة وحده لا يحدد إن كان السبب حملًا أو هرمونات أو حالة أخرى."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Arrange assessment after three missed periods, or earlier if there are other concerns. Take previous test results and medicine details. Ask what the proposed blood tests look for and when to review. Severe pain or faintness with possible pregnancy needs urgent care, not a routine appointment.", "رتّبي تقييمًا بعد غياب ثلاث دورات أو أبكر عند مخاوف أخرى. أحضري نتائج الفحوص والأدوية. اسألي عن هدف التحاليل وموعد المراجعة. الألم الشديد أو الدوخة مع احتمال الحمل يحتاج رعاية عاجلة وليس موعدًا روتينيًا."]}]}, "pms": {"understand": ["Premenstrual symptoms can affect mood, sleep, appetite and the body. Severe symptoms may be described as PMDD and deserve treatment.", "قد تؤثر أعراض ما قبل الحيض في المزاج والنوم والشهية والجسم. وقد تُسمّى الأعراض الشديدة اضطراب ما قبل الحيض الاكتئابي وتستحق العلاج."], "assessment": ["A diary across two cycles helps show timing and impact. Record symptom-free days as well as difficult days.", "يساعد سجل خلال دورتين على توضيح التوقيت والتأثير. دوّني الأيام الخالية من الأعراض أيضًا."], "options": ["Regular sleep, activity and stress support may help. Discuss psychological therapy, hormonal treatment or antidepressants when appropriate.", "قد يفيد انتظام النوم والنشاط ودعم التعامل مع التوتر. ناقشي العلاج النفسي أو الهرموني أو مضادات الاكتئاب عند مناسبتها."], "faq": [["Should severe mood symptoms wait until my next cycle?", "هل أنتظر الدورة التالية مع أعراض مزاجية شديدة؟", "No. Seek help promptly; immediate danger to yourself needs emergency support.", "لا. اطلبي المساعدة سريعًا؛ والخطر الفوري على نفسك يستدعي مساعدة طارئة."]], "questions": [["Could this pattern be PMS, PMDD or another condition?", "هل يتوافق النمط مع أعراض ما قبل الحيض أو اضطرابها الاكتئابي أو حالة أخرى؟"], ["Which treatment fits my mood symptoms and contraception needs?", "ما العلاج الملائم للمزاج واحتياجات منع الحمل لديّ؟"]], "related": ["postnatal-mood", "perimenopause"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Premenstrual symptoms can affect mood, sleep, appetite and the body. Severe symptoms may be described as PMDD and deserve treatment.", "قد تؤثر أعراض ما قبل الحيض في المزاج والنوم والشهية والجسم. وقد تُسمّى الأعراض الشديدة اضطراب ما قبل الحيض الاكتئابي وتستحق العلاج."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["A diary across two cycles helps show timing and impact. Record symptom-free days as well as difficult days.", "يساعد سجل خلال دورتين على توضيح التوقيت والتأثير. دوّني الأيام الخالية من الأعراض أيضًا."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Regular sleep, activity and stress support may help. Discuss psychological therapy, hormonal treatment or antidepressants when appropriate.", "قد يفيد انتظام النوم والنشاط ودعم التعامل مع التوتر. ناقشي العلاج النفسي أو الهرموني أو مضادات الاكتئاب عند مناسبتها."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Track mood and physical symptoms alongside period dates for at least two cycles if you can. Include days when you feel well. A pattern helps distinguish symptoms linked to the cycle from symptoms present most of the month. Do not delay help for severe distress while collecting a diary.", "تابعي المزاج والأعراض الجسدية مع تواريخ الدورة لدورتين على الأقل إن استطعت، بما فيها أيام التحسن. يساعد النمط في تمييز الأعراض المرتبطة بالدورة عن المستمرة معظم الشهر. لا تؤخري المساعدة للضيق الشديد لجمع السجل."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Bring the diary and identify the symptom affecting you most. Ask about self-care, talking therapy and medicine choices, including possible side effects. If mood symptoms severely affect daily life, ask whether a more severe premenstrual condition or another mental-health condition needs assessment.", "أحضري السجل وحددي أكثر الأعراض تأثيرًا. اسألي عن العناية الذاتية والعلاج النفسي والدوائي وآثاره الجانبية. إذا أثرت الأعراض المزاجية بشدة في حياتك فاسألي عن تقييم حالة أشد قبل الحيض أو مشكلة نفسية أخرى."]}]}, "pcos": {"understand": ["This condition can affect more than periods: skin, hair, fertility and metabolic health may be involved. Similar symptoms have other causes.", "قد تتجاوز هذه الحالة اضطراب الدورة لتؤثر في الجلد والشعر والخصوبة وصحة الاستقلاب. وللأعراض المشابهة أسباب أخرى."], "assessment": ["Assessment may include hormone tests and metabolic checks. Ultrasound is not a stand-alone diagnosis; assessment in adolescents differs.", "قد يتضمن التقييم فحوص الهرمونات والاستقلاب. لا يكفي التصوير وحده للتشخيص، ويختلف التقييم عند المراهقات."], "options": ["Agree priorities: managing bleeding, hair or acne symptoms, metabolic health, or fertility. Treatment choices depend on pregnancy plans.", "حددي الأولويات: تنظيم النزف أو أعراض الشعر والحبوب أو صحة الاستقلاب أو الخصوبة. تتأثر الخيارات بخطط الحمل."], "faq": [["Is PCOS the same as one ovarian cyst?", "هل تكيس المبايض هو نفسه كيس منفرد بالمبيض؟", "No. A single cyst and this hormone condition are different issues.", "لا. الكيس المنفرد وهذه الحالة الهرمونية مشكلتان مختلفتان."]], "questions": [["What follow-up do I need if periods remain infrequent?", "ما المتابعة المطلوبة إذا بقيت الدورة متباعدة؟"], ["What metabolic checks and symptom treatments are appropriate?", "ما فحوص الاستقلاب وعلاجات الأعراض المناسبة؟"]], "related": ["missed-periods", "fertility-assessment", "cysts"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["This condition can affect more than periods: skin, hair, fertility and metabolic health may be involved. Similar symptoms have other causes.", "قد تتجاوز هذه الحالة اضطراب الدورة لتؤثر في الجلد والشعر والخصوبة وصحة الاستقلاب. وللأعراض المشابهة أسباب أخرى."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Assessment may include hormone tests and metabolic checks. Ultrasound is not a stand-alone diagnosis; assessment in adolescents differs.", "قد يتضمن التقييم فحوص الهرمونات والاستقلاب. لا يكفي التصوير وحده للتشخيص، ويختلف التقييم عند المراهقات."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Agree priorities: managing bleeding, hair or acne symptoms, metabolic health, or fertility. Treatment choices depend on pregnancy plans.", "حددي الأولويات: تنظيم النزف أو أعراض الشعر والحبوب أو صحة الاستقلاب أو الخصوبة. تتأثر الخيارات بخطط الحمل."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Choose your priorities: irregular bleeding, skin or hair changes, fertility, energy or mood. These concerns may need different approaches. Bring cycle records and previous results. PCOS is not diagnosed from an app checklist, and symptoms can overlap with other conditions.", "حددي أولوياتك: اضطراب النزف أو الجلد والشعر أو الخصوبة أو الطاقة أو المزاج. قد تحتاج هذه المخاوف طرقًا مختلفة. أحضري سجل الدورة والنتائج السابقة. لا يُشخّص تكيس المبايض بقائمة تطبيق وقد تتشابه الأعراض مع حالات أخرى."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask what follow-up is needed for your periods and longer-term metabolic health. Discuss which treatments fit pregnancy plans. If one concern improves but another persists, request a revised plan. You may see PMOS terminology on the linked NHS page; ask your clinician to explain the terminology used locally.", "اسألي عن متابعة الدورة والصحة الأيضية لاحقًا وعن ملاءمة العلاج لخطط الحمل. إذا تحسنت مشكلة واستمرت أخرى فاطلبي تعديل الخطة. قد يظهر مصطلح PMOS في مصدر NHS؛ اسألي المختص عن المصطلح المستخدم محليًا."]}]}, "endometriosis": {"understand": ["Pain may occur with periods, sex, bowel movements or urination. Fatigue and fertility difficulties can also affect everyday life.", "قد يحدث الألم مع الدورة أو الجماع أو التبرز أو التبول. وقد يؤثر التعب وصعوبة الإنجاب في الحياة اليومية."], "assessment": ["Discuss symptom patterns and family history. Assessment may involve examination, ultrasound, MRI or laparoscopy depending on the situation.", "ناقشي نمط الأعراض والتاريخ العائلي. قد يشمل التقييم الفحص أو الموجات الصوتية أو الرنين أو المنظار بحسب الحالة."], "options": ["Treatment aims to manage symptoms. Discuss pain management, hormonal options, surgery and how pregnancy plans affect decisions.", "يهدف العلاج إلى ضبط الأعراض. ناقشي تدبير الألم والخيارات الهرمونية والجراحة وتأثير خطط الحمل في القرارات."], "faq": [["What if initial treatment does not help?", "ماذا إن لم يفد العلاج الأول؟", "Ask for reassessment and whether specialist endometriosis care is appropriate.", "اطلبي إعادة التقييم واسألي عن ملاءمة الإحالة إلى خدمة متخصصة."]], "questions": [["What is the next step if my symptoms persist?", "ما الخطوة التالية إذا استمرت أعراضي؟"], ["How will each option affect my fertility plans?", "كيف يؤثر كل خيار في خطط الإنجاب لديّ؟"]], "related": ["period-pain", "pain-sex", "fertility-assessment"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Pain may occur with periods, sex, bowel movements or urination. Fatigue and fertility difficulties can also affect everyday life.", "قد يحدث الألم مع الدورة أو الجماع أو التبرز أو التبول. وقد يؤثر التعب وصعوبة الإنجاب في الحياة اليومية."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Discuss symptom patterns and family history. Assessment may involve examination, ultrasound, MRI or laparoscopy depending on the situation.", "ناقشي نمط الأعراض والتاريخ العائلي. قد يشمل التقييم الفحص أو الموجات الصوتية أو الرنين أو المنظار بحسب الحالة."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Treatment aims to manage symptoms. Discuss pain management, hormonal options, surgery and how pregnancy plans affect decisions.", "يهدف العلاج إلى ضبط الأعراض. ناقشي تدبير الألم والخيارات الهرمونية والجراحة وتأثير خطط الحمل في القرارات."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Keep a pain record that includes bowel, bladder, sexual and period symptoms and their effect on daily life. Note treatments tried and whether they helped. Ask for support with fatigue, mood and work or study difficulties as well as pain.", "احتفظي بسجل للألم يشمل أعراض الأمعاء والمثانة والجماع والدورة وتأثيرها اليومي. دوّني العلاجات التي جربتها وفائدتها. اطلبي دعم التعب والمزاج وصعوبات العمل أو الدراسة إلى جانب الألم."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask what each test could clarify and what happens if symptoms persist. Treatment aims to manage symptoms; options have different implications for pregnancy plans. If treatment is ineffective or symptoms are severe, ask whether specialist endometriosis care is appropriate and who will coordinate follow-up.", "اسألي ما الذي يوضحه كل فحص وما التالي إذا استمرت الأعراض. يهدف العلاج لتخفيفها وللخيارات آثار مختلفة على خطط الحمل. إذا لم يفد العلاج أو كانت الأعراض شديدة فاسألي عن ملاءمة رعاية متخصصة ومن ينسق المتابعة."]}]}, "fibroids": {"understand": ["Symptoms can include heavy bleeding, pressure and bowel or bladder problems. Size, position and number influence the effect of fibroids.", "قد تشمل الأعراض غزارة النزف والضغط ومشكلات الأمعاء أو المثانة. ويؤثر حجم الأورام وموقعها وعددها في تأثيرها."], "assessment": ["Ultrasound helps map the fibroids. Discuss which symptoms they explain and whether another cause also needs assessment.", "يساعد التصوير بالموجات الصوتية في تحديد الأورام. ناقشي أي أعراض تفسّرها والحاجة لتقييم أسباب أخرى."], "options": ["Monitoring, bleeding treatments, fibroid removal, embolisation or hysterectomy may be discussed. Benefits and effects on future pregnancy differ.", "قد تُناقش المتابعة أو علاجات النزف أو استئصال الأورام أو قسطرة شرايينها أو استئصال الرحم. تختلف الفوائد وتأثيراتها في الحمل مستقبلًا."], "faq": [["Does every fibroid need surgery?", "هل يحتاج كل ورم ليفي إلى جراحة؟", "No. Fibroids without troublesome symptoms may need no treatment.", "لا. قد لا تحتاج الأورام غير المسببة لأعراض مزعجة إلى علاج."]], "questions": [["Which fibroid is likely to explain my symptoms?", "أي ورم قد يفسّر أعراضي؟"], ["What are the benefits and disadvantages of keeping my womb?", "ما فوائد وسلبيات الخيارات التي تحافظ على الرحم؟"]], "related": ["heavy-periods", "fertility-assessment"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Symptoms can include heavy bleeding, pressure and bowel or bladder problems. Size, position and number influence the effect of fibroids.", "قد تشمل الأعراض غزارة النزف والضغط ومشكلات الأمعاء أو المثانة. ويؤثر حجم الأورام وموقعها وعددها في تأثيرها."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Ultrasound helps map the fibroids. Discuss which symptoms they explain and whether another cause also needs assessment.", "يساعد التصوير بالموجات الصوتية في تحديد الأورام. ناقشي أي أعراض تفسّرها والحاجة لتقييم أسباب أخرى."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Monitoring, bleeding treatments, fibroid removal, embolisation or hysterectomy may be discussed. Benefits and effects on future pregnancy differ.", "قد تُناقش المتابعة أو علاجات النزف أو استئصال الأورام أو قسطرة شرايينها أو استئصال الرحم. تختلف الفوائد وتأثيراتها في الحمل مستقبلًا."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Ask where the fibroids are, their size and whether they explain your symptoms. A fibroid found on a scan does not automatically require treatment. Record bleeding, pressure, bladder symptoms and the effect on your life, and tell the team about future pregnancy plans.", "اسألي عن موقع الأورام الليفية وحجمها وهل تفسر أعراضك. وجود ورم ليفي بالتصوير لا يستلزم العلاج تلقائيًا. دوّني النزف والضغط وأعراض المثانة وتأثيرها اليومي، وأخبري الفريق بخطط الحمل."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Compare the aims of medicines and procedures: symptom control, shrinking or removing fibroids, or treating the uterus more extensively. Ask about recovery, possible recurrence and fertility effects. If monitoring is chosen, clarify which changes should bring you back sooner.", "قارني أهداف الأدوية والإجراءات: ضبط الأعراض أو تقليص الأورام أو إزالتها أو علاج أوسع للرحم. اسألي عن التعافي واحتمال العودة وأثر الخصوبة. إذا اختيرت المتابعة فحددي التغيرات التي تستدعي العودة أبكر."]}]}, "cysts": {"understand": ["Many cysts relate to the cycle and disappear. Others need follow-up. New severe pain can occur with rupture or twisting.", "ترتبط أكياس كثيرة بالدورة وتختفي، بينما يحتاج بعضها متابعة. وقد يحدث ألم شديد جديد مع الانفجار أو الالتواء."], "assessment": ["Ultrasound appearance, symptoms and menopause status guide decisions. A blood marker alone cannot establish a cancer diagnosis.", "يوجّه مظهر التصوير والأعراض وحالة انقطاع الطمث القرارات. لا يثبت مؤشر دموي وحده تشخيص السرطان."], "options": ["Ask whether observation, repeat scanning or surgery is advised, and what changes should bring you back sooner.", "اسألي عن المتابعة أو إعادة التصوير أو الجراحة، وعن التغيّرات التي تستدعي العودة مبكرًا."], "faq": [["Does an ovarian cyst automatically mean infertility?", "هل يعني كيس المبيض العقم حتمًا؟", "No. Fertility is usually unaffected, but the type of cyst and treatment matter.", "لا. غالبًا لا تتأثر الخصوبة، لكن نوع الكيس والعلاج مهمان."]], "questions": [["What does my scan show and when should it be repeated?", "ماذا يُظهر الفحص ومتى يُعاد؟"], ["If surgery is needed, can ovarian tissue be preserved?", "إن لزمت الجراحة، هل يمكن الحفاظ على نسيج المبيض؟"]], "related": ["pcos", "bloating", "endometriosis"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Many cysts relate to the cycle and disappear. Others need follow-up. New severe pain can occur with rupture or twisting.", "ترتبط أكياس كثيرة بالدورة وتختفي، بينما يحتاج بعضها متابعة. وقد يحدث ألم شديد جديد مع الانفجار أو الالتواء."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Ultrasound appearance, symptoms and menopause status guide decisions. A blood marker alone cannot establish a cancer diagnosis.", "يوجّه مظهر التصوير والأعراض وحالة انقطاع الطمث القرارات. لا يثبت مؤشر دموي وحده تشخيص السرطان."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Ask whether observation, repeat scanning or surgery is advised, and what changes should bring you back sooner.", "اسألي عن المتابعة أو إعادة التصوير أو الجراحة، وعن التغيّرات التي تستدعي العودة مبكرًا."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Ask what the ultrasound says about the cyst’s appearance and size. Many cysts resolve, but the plan depends on symptoms and menopause status as well as the scan. Do not interpret an isolated blood-test result as a cancer diagnosis.", "اسألي عما يوضحه التصوير عن شكل الكيس وحجمه. تزول أكياس كثيرة لكن الخطة تعتمد أيضًا على الأعراض وحالة انقطاع الطمث. لا تفسري نتيجة تحليل منفردة كتشخيص سرطان."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If repeat imaging is planned, record when it is due and who will review it. Before surgery, ask whether the cyst or ovary may be removed and how fertility could be affected. Sudden severe pain or pain with vomiting needs urgent assessment rather than waiting for a follow-up scan.", "إذا خُطط لتصوير متكرر فسجّلي موعده ومن يراجعه. قبل الجراحة اسألي عن إزالة الكيس أو المبيض وأثر الخصوبة. الألم الشديد المفاجئ أو المصحوب بقيء يحتاج تقييمًا عاجلًا دون انتظار التصوير التالي."]}]}, "discharge": {"understand": ["Normal discharge varies through the cycle. A new smell, itch, soreness or bleeding can reflect infection or irritation; appearance alone is unreliable.", "تتغيّر الإفرازات الطبيعية خلال الدورة. قد تعكس رائحة جديدة أو حكة أو ألم أو نزف عدوى أو تهيّجًا؛ ولا يكفي المظهر وحده."], "assessment": ["Describe changes, discomfort and products used. Ask whether examination or infection testing is appropriate instead of repeatedly self-treating.", "صفي التغيرات والانزعاج والمنتجات المستخدمة. اسألي عن الحاجة للفحص أو اختبار العدوى بدل تكرار العلاج الذاتي."], "options": ["Gently clean the outside. Avoid douching and perfumed products. Treatment should address the identified cause.", "نظفي الجلد الخارجي بلطف، وتجنّبي الغسول الداخلي والمنتجات المعطّرة. ينبغي أن يعالج العلاج السبب المحدد."], "faq": [["Does white discharge always mean thrush?", "هل تعني الإفرازات البيضاء الفطريات دائمًا؟", "No. Discharge can be normal, and different conditions can overlap.", "لا. قد تكون الإفرازات طبيعية وقد تتشابه مظاهر حالات مختلفة."]], "questions": [["Do I need a swab or another test?", "هل أحتاج مسحة أو فحصًا آخر؟"], ["What should I do if symptoms return?", "ماذا أفعل إذا عادت الأعراض؟"]], "related": ["sti", "pain-sex", "uti"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Normal discharge varies through the cycle. A new smell, itch, soreness or bleeding can reflect infection or irritation; appearance alone is unreliable.", "تتغيّر الإفرازات الطبيعية خلال الدورة. قد تعكس رائحة جديدة أو حكة أو ألم أو نزف عدوى أو تهيّجًا؛ ولا يكفي المظهر وحده."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Describe changes, discomfort and products used. Ask whether examination or infection testing is appropriate instead of repeatedly self-treating.", "صفي التغيرات والانزعاج والمنتجات المستخدمة. اسألي عن الحاجة للفحص أو اختبار العدوى بدل تكرار العلاج الذاتي."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Gently clean the outside. Avoid douching and perfumed products. Treatment should address the identified cause.", "نظفي الجلد الخارجي بلطف، وتجنّبي الغسول الداخلي والمنتجات المعطّرة. ينبغي أن يعالج العلاج السبب المحدد."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Notice changes from your usual discharge, especially smell, colour, itching, soreness, pain or bleeding. Avoid douching or using scented products to cover a smell. Colour alone cannot identify the cause, and repeated treatment for presumed thrush may miss another problem.", "لاحظي تغير الإفرازات عن المعتاد خصوصًا الرائحة واللون والحكة والألم والنزف. تجنبي الغسول الداخلي أو المعطرات لإخفاء الرائحة. اللون وحده لا يحدد السبب وقد يفوّت تكرار علاج فطريات مفترضة مشكلة أخرى."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask whether a swab, urine test or sexual-health assessment is appropriate. Tell the clinician if you are pregnant and about recent treatments. Confirm how results will reach you and whether a partner needs assessment. Return if symptoms persist or change after treatment.", "اسألي عن ملاءمة المسحة أو فحص البول أو تقييم الصحة الجنسية. اذكري الحمل والعلاجات الحديثة. حددي طريقة استلام النتائج والحاجة لتقييم الشريك. عودي إذا استمرت الأعراض أو تغيرت بعد العلاج."]}]}, "uti": {"understand": ["Burning, urgency and frequency may indicate infection. Fever or pain near the ribs can indicate kidney involvement and needs prompt care.", "قد يدل الحرقان والإلحاح وكثرة التبول على عدوى. وقد تشير الحرارة أو ألم قرب الأضلاع إلى إصابة الكلى وتحتاج رعاية سريعة."], "assessment": ["A urine test may be needed. Mention pregnancy, diabetes, repeated infections and recent antibiotics because these affect management.", "قد يلزم تحليل البول. اذكري الحمل والسكري وتكرر العدوى والمضادات الحديثة لأنها تؤثر في التدبير."], "options": ["Treatment depends on your situation. Take prescribed antibiotics as directed; seek reassessment if symptoms worsen or fail to improve.", "يعتمد العلاج على حالتك. خذي المضاد الموصوف وفق التعليمات، واطلبي إعادة التقييم عند التدهور أو عدم التحسن."], "faq": [["Can cranberry products treat an established UTI?", "هل تعالج منتجات التوت البري عدوى بولية قائمة؟", "They should not replace assessment and treatment of an existing infection.", "لا ينبغي أن تحل محل تقييم العدوى القائمة وعلاجها."]], "questions": [["Do my repeated symptoms need further investigation?", "هل تحتاج الأعراض المتكررة إلى فحوص إضافية؟"], ["When should I contact you if treatment is not helping?", "متى أتواصل إذا لم يفد العلاج؟"]], "related": ["discharge", "pelvic-floor", "pregnancy-conditions"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Burning, urgency and frequency may indicate infection. Fever or pain near the ribs can indicate kidney involvement and needs prompt care.", "قد يدل الحرقان والإلحاح وكثرة التبول على عدوى. وقد تشير الحرارة أو ألم قرب الأضلاع إلى إصابة الكلى وتحتاج رعاية سريعة."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["A urine test may be needed. Mention pregnancy, diabetes, repeated infections and recent antibiotics because these affect management.", "قد يلزم تحليل البول. اذكري الحمل والسكري وتكرر العدوى والمضادات الحديثة لأنها تؤثر في التدبير."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Treatment depends on your situation. Take prescribed antibiotics as directed; seek reassessment if symptoms worsen or fail to improve.", "يعتمد العلاج على حالتك. خذي المضاد الموصوف وفق التعليمات، واطلبي إعادة التقييم عند التدهور أو عدم التحسن."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Record burning, urgency, frequency and any fever or back pain. Tell the service if you are pregnant or have recurrent infections. Drink enough to avoid dehydration if you have no fluid restriction. Do not use leftover antibiotics or assume every urinary symptom is an infection.", "دوّني الحرقة والإلحاح والتكرار وأي حرارة أو ألم ظهر. اذكري الحمل أو تكرر الالتهاب. اشربي لتجنب الجفاف إن لم يوجد تقييد للسوائل. لا تستخدمي مضادًا متبقيًا ولا تفترضي أن كل عرض بولي التهاب."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If treatment is prescribed, follow its instructions and ask when improvement is expected. Symptoms that worsen or fail to improve need review. Recurrent symptoms deserve a prevention and assessment plan rather than repeatedly relying on the same treatment without reassessment.", "إذا وُصف علاج فاتبعي تعليماته واسألي عن وقت التحسن المتوقع. التفاقم أو غياب التحسن يحتاج مراجعة. تستحق الأعراض المتكررة خطة تقييم ووقاية بدل الاعتماد المتكرر على العلاج نفسه دون إعادة تقييم."]}]}, "sti": {"understand": ["An infection may cause no symptoms. Symptoms, relationship status or a partner looking well cannot reliably exclude an STI.", "قد لا تسبب العدوى أعراضًا. ولا تستبعدها الأعراض أو الحالة الاجتماعية أو ظهور الشريك بصحة جيدة بشكل موثوق."], "assessment": ["Tests may use urine, swabs or blood. Timing and repeat testing depend on the exposure and the infection being checked.", "قد تشمل الفحوص البول أو المسحات أو الدم. يتوقف توقيتها وتكرارها على التعرض والعدوى المراد فحصها."], "options": ["Treatment is infection-specific. Ask about partner testing, treatment completion and when sex can safely resume. Confidentiality arrangements vary locally.", "يختلف العلاج حسب العدوى. اسألي عن فحص الشريك وإكمال العلاج وموعد استئناف العلاقة بأمان. تختلف ترتيبات السرية محليًا."], "faq": [["Should I wait for symptoms before seeking advice?", "هل أنتظر الأعراض قبل طلب المشورة؟", "No. Ask after a possible exposure; the service can advise suitable test timing.", "لا. اسألي بعد التعرض المحتمل؛ تحدد الخدمة توقيت الفحص المناسب."]], "questions": [["Which tests and repeat dates fit my exposure?", "ما الفحوص ومواعيد إعادتها المناسبة للتعرض؟"], ["How is my information kept confidential here?", "كيف تُحفظ سرية معلوماتي هنا؟"]], "related": ["discharge", "emergency-contraception", "screening"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["An infection may cause no symptoms. Symptoms, relationship status or a partner looking well cannot reliably exclude an STI.", "قد لا تسبب العدوى أعراضًا. ولا تستبعدها الأعراض أو الحالة الاجتماعية أو ظهور الشريك بصحة جيدة بشكل موثوق."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Tests may use urine, swabs or blood. Timing and repeat testing depend on the exposure and the infection being checked.", "قد تشمل الفحوص البول أو المسحات أو الدم. يتوقف توقيتها وتكرارها على التعرض والعدوى المراد فحصها."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Treatment is infection-specific. Ask about partner testing, treatment completion and when sex can safely resume. Confidentiality arrangements vary locally.", "يختلف العلاج حسب العدوى. اسألي عن فحص الشريك وإكمال العلاج وموعد استئناف العلاقة بأمان. تختلف ترتيبات السرية محليًا."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["A person can have an STI without obvious symptoms. Testing depends on exposure and timing; ask when to test and whether a repeat is needed. Avoid relying on appearance or a partner feeling well. Ask the clinic about confidentiality and what information will be recorded.", "قد توجد عدوى منقولة جنسيًا دون أعراض واضحة. يعتمد الفحص على التعرض والتوقيت؛ اسألي عن موعده والحاجة لتكراره. لا تعتمدي على المظهر أو شعور الشريك بالعافية. اسألي العيادة عن السرية والمعلومات المسجلة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If a test is positive, ask about treatment, partner notification and when sexual contact can safely resume. Follow the specific service instructions rather than a generic app interval. Seek prompt care for pelvic pain or other concerning symptoms, and tell the team about possible pregnancy.", "إذا كانت النتيجة إيجابية فاسألي عن العلاج وإبلاغ الشريك وموعد استئناف التواصل الجنسي بأمان. اتبعي تعليمات الخدمة بدل فترة عامة من تطبيق. اطلبي رعاية سريعة لألم الحوض أو الأعراض المقلقة واذكري احتمال الحمل."]}]}, "emergency-contraception": {"understand": ["Options include a copper IUD and emergency pills. They have different time windows; seek advice as soon as possible.", "تشمل الخيارات اللولب النحاسي والحبوب الطارئة. تختلف المهلة بين الوسائل؛ اطلبي النصيحة بأسرع وقت."], "assessment": ["Tell the service when sex occurred, any further exposures, your regular contraception and medicines. Local availability differs.", "أخبري الخدمة بوقت الجماع وأي تعرض لاحق ووسيلة منع الحمل المعتادة والأدوية. تختلف الإتاحة محليًا."], "options": ["The copper IUD is the most effective option. Ask which method is suitable and what ongoing contraception you need.", "اللولب النحاسي هو الخيار الأكثر فعالية. اسألي عن ملاءمة الوسيلة ومنع الحمل المستمر الذي تحتاجينه."], "faq": [["Is it worth asking if I am unsure of the timing?", "هل أطلب المشورة إن لم أتأكد من التوقيت؟", "Yes. Contact a qualified service promptly rather than deciding you are too late.", "نعم. تواصلي سريعًا مع خدمة مؤهلة بدل افتراض فوات الفرصة."]], "questions": [["Which option is suitable given my timing and medicines?", "ما الخيار المناسب للتوقيت والأدوية لديّ؟"], ["When should I test and restart my regular method?", "متى أجري الاختبار وأستأنف وسيلتي المعتادة؟"]], "related": ["sti", "missed-periods"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Options include a copper IUD and emergency pills. They have different time windows; seek advice as soon as possible.", "تشمل الخيارات اللولب النحاسي والحبوب الطارئة. تختلف المهلة بين الوسائل؛ اطلبي النصيحة بأسرع وقت."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Tell the service when sex occurred, any further exposures, your regular contraception and medicines. Local availability differs.", "أخبري الخدمة بوقت الجماع وأي تعرض لاحق ووسيلة منع الحمل المعتادة والأدوية. تختلف الإتاحة محليًا."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["The copper IUD is the most effective option. Ask which method is suitable and what ongoing contraception you need.", "اللولب النحاسي هو الخيار الأكثر فعالية. اسألي عن ملاءمة الوسيلة ومنع الحمل المستمر الذي تحتاجينه."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Contact a pharmacist or sexual-health service as soon as possible after unprotected sex or contraceptive failure. Tell them when it happened, your current contraception and other medicines. The suitable option depends on timing and circumstances; do not wait for the next period to ask.", "تواصلي بأسرع ما يمكن مع الصيدلي أو خدمة الصحة الجنسية بعد جماع غير محمي أو فشل الوسيلة. اذكري التوقيت والوسيلة الحالية والأدوية الأخرى. يعتمد الخيار على التوقيت والحالة؛ لا تنتظري الدورة التالية للسؤال."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask when to restart or begin regular contraception, whether extra protection is needed and when to take a pregnancy test. Instructions differ by the emergency option used. Emergency contraception does not provide STI protection; ask about testing where relevant.", "اسألي عن بدء أو استئناف الوسيلة المنتظمة والحماية الإضافية وموعد اختبار الحمل. تختلف التعليمات حسب الخيار الطارئ. لا يوفر منع الحمل الطارئ حماية من العدوى الجنسية؛ اسألي عن الفحص عند الحاجة."]}]}, "screening": {"understand": ["Screening checks for changes that could lead to cervical cancer. It does not investigate every cause of bleeding or pelvic pain.", "يبحث التحري عن تغيرات قد تؤدي لسرطان عنق الرحم، ولا يفحص جميع أسباب النزف أو ألم الحوض."], "assessment": ["A clinician may use a speculum and soft brush to collect a cervical sample. Explain pain, anxiety or accessibility needs beforehand.", "قد يستخدم المختص منظارًا مهبليًا وفرشاة ناعمة لأخذ عينة من عنق الرحم. اشرحي مسبقًا الألم أو القلق أو احتياجات التيسير."], "options": ["Follow the instructions accompanying your result. HPV or cell changes may lead to repeat testing or closer examination with colposcopy.", "اتبعي التعليمات المرافقة للنتيجة. قد يؤدي وجود الفيروس أو تغيرات الخلايا لإعادة الفحص أو تقييم أدق بتنظير عنق الرحم."], "faq": [["Does a positive HPV result mean cancer?", "هل تعني إيجابية فيروس الورم الحليمي وجود سرطان؟", "No. It indicates a need to follow the recommended next steps.", "لا. تعني ضرورة اتباع الخطوات التالية الموصى بها."]], "sources": [["NHS: screening appointment", "https://www.nhs.uk/tests-and-treatments/cervical-screening/what-happens/"], ["NHS: screening results", "https://www.nhs.uk/tests-and-treatments/cervical-screening/your-results/"]], "questions": [["What does my exact result mean and when is follow-up due?", "ماذا تعني نتيجتي بالتحديد ومتى المتابعة؟"], ["What can make the examination more comfortable for me?", "ما الذي يجعل الفحص أكثر راحة لي؟"]], "related": ["hpv", "examination", "postmenopausal-bleeding"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Screening checks for changes that could lead to cervical cancer. It does not investigate every cause of bleeding or pelvic pain.", "يبحث التحري عن تغيرات قد تؤدي لسرطان عنق الرحم، ولا يفحص جميع أسباب النزف أو ألم الحوض."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["A clinician may use a speculum and soft brush to collect a cervical sample. Explain pain, anxiety or accessibility needs beforehand.", "قد يستخدم المختص منظارًا مهبليًا وفرشاة ناعمة لأخذ عينة من عنق الرحم. اشرحي مسبقًا الألم أو القلق أو احتياجات التيسير."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Follow the instructions accompanying your result. HPV or cell changes may lead to repeat testing or closer examination with colposcopy.", "اتبعي التعليمات المرافقة للنتيجة. قد يؤدي وجود الفيروس أو تغيرات الخلايا لإعادة الفحص أو تقييم أدق بتنظير عنق الرحم."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Screening is intended to detect risk or changes before symptoms develop. Tell the service if you have bleeding after sex, between periods or other symptoms; these need their own assessment. Ask what test your local programme uses and whether you are eligible.", "يهدف التحري لكشف الخطر أو التغيرات قبل الأعراض. اذكري النزف بعد الجماع أو بين الدورات أو الأعراض الأخرى؛ فهي تحتاج تقييمًا منفصلًا. اسألي عن اختبار البرنامج المحلي ومدى أهليتك."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Before the appointment, ask what the procedure involves and about comfort, a chaperone or stopping if needed. Afterwards, find out when results are expected and what each possible result means. An abnormal screening result is not automatically cancer; follow the recommended next step.", "قبل الموعد اسألي عن الإجراء والراحة والمرافق المهني والتوقف عند الحاجة. بعده حددي موعد النتائج ومعنى احتمالاتها. النتيجة غير الطبيعية لا تعني السرطان تلقائيًا؛ اتبعي الخطوة التالية الموصى بها."]}]}, "hpv": {"understand": ["HPV is common. Some types are associated with cancers or genital warts. Vaccination reduces risk but does not remove every risk.", "فيروس الورم الحليمي شائع. ترتبط بعض أنواعه بالسرطانات أو الثآليل التناسلية. يقلل التطعيم الخطر لكنه لا يلغيه كله."], "assessment": ["Bring previous vaccine dates. Eligibility, catch-up programmes and dose schedules vary by country and health circumstances.", "أحضري تواريخ الجرعات السابقة. تختلف الأهلية وبرامج الاستدراك وعدد الجرعات حسب البلد والحالة الصحية."], "options": ["Ask about completing the appropriate course. Mention previous severe vaccine reactions and pregnancy or breastfeeding when arranging vaccination.", "اسألي عن استكمال الجدول المناسب. اذكري التحسس الشديد السابق للقاحات والحمل أو الرضاعة عند ترتيب التطعيم."], "faq": [["Can vaccination replace cervical screening?", "هل يغني التطعيم عن فحص عنق الرحم؟", "No. Follow your local screening programme when eligible.", "لا. اتبعي برنامج التحري المحلي عند استحقاقه."]], "questions": [["Am I eligible for routine or catch-up vaccination here?", "هل أستحق التطعيم الروتيني أو الاستدراكي هنا؟"], ["How do my previous doses affect the remaining schedule?", "كيف تؤثر الجرعات السابقة في الجدول المتبقي؟"]], "related": ["screening", "sti"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["HPV is common. Some types are associated with cancers or genital warts. Vaccination reduces risk but does not remove every risk.", "فيروس الورم الحليمي شائع. ترتبط بعض أنواعه بالسرطانات أو الثآليل التناسلية. يقلل التطعيم الخطر لكنه لا يلغيه كله."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Bring previous vaccine dates. Eligibility, catch-up programmes and dose schedules vary by country and health circumstances.", "أحضري تواريخ الجرعات السابقة. تختلف الأهلية وبرامج الاستدراك وعدد الجرعات حسب البلد والحالة الصحية."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Ask about completing the appropriate course. Mention previous severe vaccine reactions and pregnancy or breastfeeding when arranging vaccination.", "اسألي عن استكمال الجدول المناسب. اذكري التحسس الشديد السابق للقاحات والحمل أو الرضاعة عند ترتيب التطعيم."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["HPV is common and can remain unnoticed. A result does not tell you exactly when infection occurred or who transmitted it. Ask whether the result concerns a screening test, visible warts or another issue; these lead to different discussions.", "فيروس الورم الحليمي شائع وقد لا يُلاحظ. لا تحدد النتيجة وقت العدوى أو من نقلها بدقة. اسألي هل تتعلق النتيجة بتحرٍّ أو ثآليل ظاهرة أو مشكلة أخرى؛ فلكل منها مناقشة مختلفة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask about vaccination eligibility and the follow-up attached to your result. Vaccination and screening serve different purposes. Keep the recommended recall date and ask how to arrange it locally. Do not assume that no symptoms means follow-up is unnecessary.", "اسألي عن أهلية اللقاح ومتابعة نتيجتك. للتطعيم والتحري أغراض مختلفة. احتفظي بموعد المتابعة واسألي كيف يُرتب محليًا. لا تفترضي أن غياب الأعراض يعني عدم الحاجة للمتابعة."]}]}, "breast": {"understand": ["Lumps can be cysts or benign growths, but some are cancer. Touch or appearance cannot reliably establish the cause.", "قد تكون الكتل أكياسًا أو أورامًا حميدة، وبعضها سرطاني. لا يحدد اللمس أو المظهر السبب بموثوقية."], "assessment": ["Assessment may include examination, ultrasound or mammography, and sometimes a needle sample. The combination depends on the findings.", "قد يشمل التقييم الفحص والموجات الصوتية أو تصوير الثدي بالأشعة، وأحيانًا عينة بالإبرة. يعتمد الاختيار على النتائج."], "options": ["Treatment follows the diagnosis. Ask how results will reach you and what to do if the change persists.", "يتبع العلاج التشخيص. اسألي كيف ستصلك النتائج وماذا تفعلين إن استمر التغير."], "faq": [["Can I ignore a lump because it does not hurt?", "هل أتجاهل الكتلة لأنها لا تؤلم؟", "No. Every new breast or armpit lump should be assessed.", "لا. ينبغي تقييم كل كتلة جديدة بالثدي أو الإبط."]], "questions": [["Which tests are needed to explain this change?", "ما الفحوص اللازمة لتفسير هذا التغير؟"], ["Who do I contact if I do not receive my results?", "بمن أتواصل إن لم تصلني النتائج؟"]], "related": ["feeding-problems", "examination"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Lumps can be cysts or benign growths, but some are cancer. Touch or appearance cannot reliably establish the cause.", "قد تكون الكتل أكياسًا أو أورامًا حميدة، وبعضها سرطاني. لا يحدد اللمس أو المظهر السبب بموثوقية."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Assessment may include examination, ultrasound or mammography, and sometimes a needle sample. The combination depends on the findings.", "قد يشمل التقييم الفحص والموجات الصوتية أو تصوير الثدي بالأشعة، وأحيانًا عينة بالإبرة. يعتمد الاختيار على النتائج."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Treatment follows the diagnosis. Ask how results will reach you and what to do if the change persists.", "يتبع العلاج التشخيص. اسألي كيف ستصلك النتائج وماذا تفعلين إن استمر التغير."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Arrange assessment for a new breast or armpit lump or an unusual nipple or skin change. Note when you noticed it and whether you are pregnant or breastfeeding. Most lumps are not cancer, but you cannot reliably identify the cause by touch or an app.", "رتّبي تقييمًا لكتلة جديدة بالثدي أو الإبط أو تغير غير معتاد بالحلمة أو الجلد. سجّلي وقت ملاحظته واذكري الحمل أو الرضاعة. معظم الكتل ليست سرطانًا لكن اللمس أو التطبيق لا يحدد السبب بدقة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Assessment may involve examination, imaging and sometimes a sample. Ask when each result will be available; not all results return together. If a change persists despite reassurance or changes again, contact the service for a review rather than waiting for routine screening.", "قد يشمل التقييم فحصًا وتصويرًا وأحيانًا عينة. اسألي عن موعد كل نتيجة؛ لا تصل النتائج كلها معًا. إذا استمر التغير رغم الطمأنة أو تغير مجددًا فتواصلي للمراجعة بدل انتظار التحري الروتيني."]}]}, "pelvic-floor": {"understand": ["A prolapse is descent of pelvic organs. Pregnancy, childbirth, ageing and repeated straining can contribute. Symptoms and severity vary.", "الهبوط هو نزول أعضاء الحوض. قد تسهم فيه الولادة والحمل والتقدم بالعمر والحزق المتكرر. تختلف الأعراض والشدة."], "assessment": ["Explain vaginal pressure, leakage and bowel difficulties. An examination helps identify the problem and guide a personalised plan.", "اشرحي الضغط المهبلي والتسرب وصعوبة التبرز. يساعد الفحص في تحديد المشكلة ووضع خطة فردية."], "options": ["Options may include specialist physiotherapy, addressing constipation, a vaginal support pessary or surgery. Mild, non-bothersome prolapse may need no intervention.", "قد تشمل الخيارات العلاج الطبيعي المتخصص وعلاج الإمساك وحلقة دعم مهبلية أو جراحة. قد لا يحتاج الهبوط البسيط غير المزعج لتدخل."], "faq": [["Is surgery the only solution?", "هل الجراحة هي الحل الوحيد؟", "No. Discuss conservative options and what matters most to you.", "لا. ناقشي الخيارات التحفظية وما يهمك أكثر."]], "questions": [["Would specialist pelvic-floor physiotherapy help me?", "هل يفيدني العلاج الطبيعي المتخصص لقاع الحوض؟"], ["What follow-up would a support pessary need?", "ما المتابعة التي تحتاجها حلقة الدعم؟"]], "related": ["uti", "pain-sex", "menopause-treatment"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["A prolapse is descent of pelvic organs. Pregnancy, childbirth, ageing and repeated straining can contribute. Symptoms and severity vary.", "الهبوط هو نزول أعضاء الحوض. قد تسهم فيه الولادة والحمل والتقدم بالعمر والحزق المتكرر. تختلف الأعراض والشدة."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Explain vaginal pressure, leakage and bowel difficulties. An examination helps identify the problem and guide a personalised plan.", "اشرحي الضغط المهبلي والتسرب وصعوبة التبرز. يساعد الفحص في تحديد المشكلة ووضع خطة فردية."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Options may include specialist physiotherapy, addressing constipation, a vaginal support pessary or surgery. Mild, non-bothersome prolapse may need no intervention.", "قد تشمل الخيارات العلاج الطبيعي المتخصص وعلاج الإمساك وحلقة دعم مهبلية أو جراحة. قد لا يحتاج الهبوط البسيط غير المزعج لتدخل."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Write down leaking, heaviness, a vaginal bulge and bladder or bowel-emptying difficulties. Ask whether a pelvic-health physiotherapy assessment would help. Advice should fit your symptoms; simply increasing exercises is not a substitute for assessing pain or a bulge.", "دوّني التسرب والثقل والبروز المهبلي وصعوبة إفراغ المثانة أو الأمعاء. اسألي عن فائدة تقييم علاج طبيعي للحوض. ينبغي أن تلائم النصائح أعراضك؛ زيادة التمارين وحدها لا تغني عن تقييم الألم أو البروز."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If prolapse is diagnosed, discuss observation, physiotherapy, a support pessary or surgery according to its effect on your life. Ask about pessary care or procedure risks and recovery. Tell the team about future pregnancy plans and agree what would prompt reassessment.", "إذا شُخّص الهبوط فناقشي المتابعة أو العلاج الطبيعي أو الحلقة الداعمة أو الجراحة حسب تأثيره في حياتك. اسألي عن العناية بالحلقة أو مخاطر الإجراء والتعافي. اذكري خطط الحمل وحددي ما يستدعي إعادة التقييم."]}]}, "pregnancy-loss": {"understand": ["Bleeding does not always mean miscarriage. Assessment is needed to understand the pregnancy’s location and development, and your health.", "لا يعني النزف دائمًا إجهاضًا. يلزم التقييم لمعرفة موضع الحمل وتطوره وحالتك الصحية."], "assessment": ["Ultrasound and sometimes blood tests may be used. Very early findings can be uncertain and may require repeat assessment.", "قد تُستخدم الموجات الصوتية وأحيانًا تحاليل الدم. قد تكون النتائج المبكرة غير حاسمة وتحتاج إعادة التقييم."], "options": ["After confirmed loss, options may include waiting, medicines or a procedure. Your condition and preferences guide the choice; emotional support matters too.", "بعد تأكيد الفقد قد تشمل الخيارات الانتظار أو الأدوية أو إجراءً طبيًا. توجّه حالتك وتفضيلاتك الاختيار، والدعم النفسي مهم أيضًا."], "faq": [["Should I manage heavy bleeding alone at home?", "هل أتعامل وحدي مع نزف غزير بالمنزل؟", "No. Heavy bleeding, severe pain or faintness needs urgent medical help.", "لا. النزف الغزير أو الألم الشديد أو الإغماء يحتاج مساعدة طبية عاجلة."]], "questions": [["Is the diagnosis certain, or do I need another scan?", "هل التشخيص مؤكد أم أحتاج تصويرًا آخر؟"], ["What should I expect and who can I call during recovery?", "ماذا أتوقع وبمن أتواصل أثناء التعافي؟"]], "related": ["ectopic", "postnatal-mood", "maternal-warning"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Bleeding does not always mean miscarriage. Assessment is needed to understand the pregnancy’s location and development, and your health.", "لا يعني النزف دائمًا إجهاضًا. يلزم التقييم لمعرفة موضع الحمل وتطوره وحالتك الصحية."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Ultrasound and sometimes blood tests may be used. Very early findings can be uncertain and may require repeat assessment.", "قد تُستخدم الموجات الصوتية وأحيانًا تحاليل الدم. قد تكون النتائج المبكرة غير حاسمة وتحتاج إعادة التقييم."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["After confirmed loss, options may include waiting, medicines or a procedure. Your condition and preferences guide the choice; emotional support matters too.", "بعد تأكيد الفقد قد تشمل الخيارات الانتظار أو الأدوية أو إجراءً طبيًا. توجّه حالتك وتفضيلاتك الاختيار، والدعم النفسي مهم أيضًا."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Bleeding does not by itself confirm a miscarriage. Assessment may need ultrasound and blood tests, sometimes repeated before the situation is clear. Ask what is known, what remains uncertain and who to contact while waiting. You do not have to manage uncertainty without support.", "النزف وحده لا يؤكد الإجهاض. قد يحتاج التقييم تصويرًا وتحاليل وأحيانًا تكرارها قبل اتضاح الحالة. اسألي عما هو معروف وغير مؤكد وجهة التواصل أثناء الانتظار. لا تحتاجين مواجهة عدم اليقين دون دعم."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If loss is confirmed, ask about the appropriate management options, expected symptoms, pain relief and follow-up. Take written instructions for when to return urgently. Emotional reactions differ; support can be useful for you and a partner. Closing a pregnancy in this app does not notify a clinician.", "إذا تأكد الفقد فاسألي عن خيارات التدبير والأعراض المتوقعة والمسكنات والمتابعة. خذي تعليمات مكتوبة للعودة العاجلة. تختلف الاستجابات العاطفية وقد يفيد الدعم لك وللشريك. إغلاق الحمل في التطبيق لا يُبلغ مختصًا."]}]}, "ectopic": {"understand": ["A pregnancy outside the womb cannot develop normally. Internal bleeding can become life-threatening, sometimes before symptoms seem dramatic.", "لا يتطور الحمل خارج الرحم بصورة طبيعية. وقد يهدد النزف الداخلي الحياة، وأحيانًا قبل أن تبدو الأعراض شديدة."], "assessment": ["Specialist assessment usually combines ultrasound and blood tests. Follow-up may be needed when the location is initially unclear.", "يجمع تقييم المختص عادةً بين التصوير والتحاليل. وقد تلزم المتابعة إذا لم يتضح الموضع في البداية."], "options": ["Selected cases may be monitored; others need medicine or surgery. Decisions depend on symptoms and results, not an app score.", "قد تُتابع حالات مختارة، بينما يحتاج غيرها دواءً أو جراحة. تعتمد القرارات على الأعراض والنتائج، وليس على تقييم التطبيق."], "faq": [["Can this happen without a positive home test?", "هل يحدث ذلك دون اختبار منزلي إيجابي؟", "Seek advice for suggestive symptoms if pregnancy is possible, even without a positive test.", "اطلبي المشورة للأعراض المقلقة مع إمكانية الحمل حتى دون اختبار إيجابي."]], "questions": [["What follow-up confirms that treatment is complete?", "ما المتابعة التي تؤكد اكتمال العلاج؟"], ["What should I arrange early in a future pregnancy?", "ما الذي أرتبه مبكرًا في الحمل المقبل؟"]], "related": ["pregnancy-loss", "missed-periods", "maternal-warning"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["A pregnancy outside the womb cannot develop normally. Internal bleeding can become life-threatening, sometimes before symptoms seem dramatic.", "لا يتطور الحمل خارج الرحم بصورة طبيعية. وقد يهدد النزف الداخلي الحياة، وأحيانًا قبل أن تبدو الأعراض شديدة."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Specialist assessment usually combines ultrasound and blood tests. Follow-up may be needed when the location is initially unclear.", "يجمع تقييم المختص عادةً بين التصوير والتحاليل. وقد تلزم المتابعة إذا لم يتضح الموضع في البداية."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Selected cases may be monitored; others need medicine or surgery. Decisions depend on symptoms and results, not an app score.", "قد تُتابع حالات مختارة، بينما يحتاج غيرها دواءً أو جراحة. تعتمد القرارات على الأعراض والنتائج، وليس على تقييم التطبيق."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Possible ectopic pregnancy needs clinical assessment, even without a positive home test. Tell the team about pain, bleeding and pregnancy possibility. Severe pain, shoulder-tip pain, fainting or collapse can require emergency care. A calculator cannot locate a pregnancy.", "احتمال الحمل خارج الرحم يحتاج تقييمًا حتى دون اختبار منزلي إيجابي. اذكري الألم والنزف واحتمال الحمل. قد يستدعي الألم الشديد أو ألم طرف الكتف أو الإغماء أو الانهيار الطوارئ. لا تحدد الحاسبة مكان الحمل."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If the pregnancy location is not yet clear, repeat tests may be arranged. Keep all follow-up appointments and ask for an urgent-contact plan. Treatment and monitoring depend on the assessment. Do not assume an improving symptom or a falling home-test line means follow-up can stop.", "إذا لم يتضح موقع الحمل فقد تُرتّب فحوص متكررة. التزمي بالمتابعة واطلبي خطة تواصل عاجل. يعتمد العلاج والمراقبة على التقييم. لا تفترضي أن تحسن عرض أو خفوت خط الاختبار المنزلي يسمح بإيقاف المتابعة."]}]}, "labour": {"understand": ["Contractions that build in strength and frequency may signal labour. A mucus show alone does not predict the exact birth time.", "قد تشير تقلصات تتزايد قوةً وتكرارًا إلى المخاض. لا تتنبأ السدادة المخاطية وحدها بموعد الولادة الدقيق."], "assessment": ["Your maternity team will ask about contractions, waters, bleeding and movements. Contact them if unsure; do not rely on a timer alone.", "يسأل فريق الولادة عن التقلصات والماء والنزف والحركة. تواصلي عند الشك ولا تعتمدي على المؤقت وحده."], "options": ["Discuss comfort measures, pain-relief preferences and where to go. If waters break, use a pad and contact maternity care promptly.", "ناقشي وسائل الراحة وتفضيلات تسكين الألم ومكان التوجه. عند نزول الماء استخدمي فوطة وتواصلي سريعًا مع قسم الولادة."], "faq": [["Should I wait until morning for reduced movements?", "هل أنتظر الصباح مع نقص حركة الجنين؟", "No. Contact maternity care immediately, including at night.", "لا. تواصلي فورًا مع قسم الولادة، حتى ليلًا."]], "questions": [["When should I call or come in given my own pregnancy?", "متى أتصل أو أحضر بحسب ظروف حملي؟"], ["What pain-relief options are available at my birth location?", "ما خيارات تسكين الألم المتاحة في مكان ولادتي؟"]], "related": ["maternal-warning", "pregnancy-conditions"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Contractions that build in strength and frequency may signal labour. A mucus show alone does not predict the exact birth time.", "قد تشير تقلصات تتزايد قوةً وتكرارًا إلى المخاض. لا تتنبأ السدادة المخاطية وحدها بموعد الولادة الدقيق."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Your maternity team will ask about contractions, waters, bleeding and movements. Contact them if unsure; do not rely on a timer alone.", "يسأل فريق الولادة عن التقلصات والماء والنزف والحركة. تواصلي عند الشك ولا تعتمدي على المؤقت وحده."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Discuss comfort measures, pain-relief preferences and where to go. If waters break, use a pad and contact maternity care promptly.", "ناقشي وسائل الراحة وتفضيلات تسكين الألم ومكان التوجه. عند نزول الماء استخدمي فوطة وتواصلي سريعًا مع قسم الولادة."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Follow your maternity team’s contact instructions. When calling, describe contractions, any fluid loss or bleeding, your pregnancy week and baby movements. If your waters break, note the time and appearance of the fluid. Do not use an app timer as permission to delay care.", "اتبعي تعليمات التواصل مع فريق الولادة. عند الاتصال صفي التقلصات وتسرب السائل أو النزف وأسبوع الحمل وحركة الجنين. إذا نزل الماء فدوّني الوقت وصفته. لا تستخدمي مؤقت التطبيق لتبرير تأخير الرعاية."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask in advance where to go, transport arrangements and who can accompany you. Bring your maternity notes and medication list. Birth preferences can change as circumstances change; ask the team to explain proposed examinations, pain-relief choices and interventions.", "اسألي مسبقًا عن وجهة المراجعة والمواصلات والمرافق. أحضري ملف الحمل وقائمة الأدوية. قد تتغير تفضيلات الولادة بحسب الظروف؛ اطلبي شرح الفحوص وخيارات تسكين الألم والتدخلات المقترحة."]}]}, "postnatal-mood": {"understand": ["Depression can involve anxiety, guilt, loss of enjoyment or difficulty bonding. Baby blues usually settle within two weeks; worsening symptoms need help earlier.", "قد يشمل الاكتئاب القلق والذنب وفقد المتعة وصعوبة الارتباط بالطفل. غالبًا تزول كآبة النفاس العابرة خلال أسبوعين؛ والتدهور يحتاج مساعدة أبكر."], "assessment": ["A clinician may ask about your feelings, sleep and safety, sometimes using a questionnaire. You need not wait until every symptom appears.", "قد يسأل المختص عن المشاعر والنوم والسلامة، وأحيانًا يستخدم استبيانًا. لا يلزم انتظار ظهور كل الأعراض."], "options": ["Talking therapies, practical support and medicines may help. Discuss breastfeeding when choosing treatment rather than avoiding care.", "قد يفيد العلاج النفسي والدعم العملي والأدوية. ناقشي الرضاعة عند اختيار العلاج بدل تجنّب الرعاية."], "faq": [["Does needing treatment make me a bad parent?", "هل تجعلني الحاجة للعلاج أمًا سيئة؟", "No. Seeking support is a step towards caring for yourself and your baby.", "لا. طلب الدعم خطوة للعناية بنفسك وبطفلك."]], "questions": [["What support can start now?", "ما الدعم الذي يمكن أن يبدأ الآن؟"], ["Which treatment fits my symptoms and feeding choices?", "ما العلاج الملائم لأعراضي وطريقة تغذية طفلي؟"]], "related": ["pms", "feeding-problems", "maternal-warning"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Depression can involve anxiety, guilt, loss of enjoyment or difficulty bonding. Baby blues usually settle within two weeks; worsening symptoms need help earlier.", "قد يشمل الاكتئاب القلق والذنب وفقد المتعة وصعوبة الارتباط بالطفل. غالبًا تزول كآبة النفاس العابرة خلال أسبوعين؛ والتدهور يحتاج مساعدة أبكر."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["A clinician may ask about your feelings, sleep and safety, sometimes using a questionnaire. You need not wait until every symptom appears.", "قد يسأل المختص عن المشاعر والنوم والسلامة، وأحيانًا يستخدم استبيانًا. لا يلزم انتظار ظهور كل الأعراض."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Talking therapies, practical support and medicines may help. Discuss breastfeeding when choosing treatment rather than avoiding care.", "قد يفيد العلاج النفسي والدعم العملي والأدوية. ناقشي الرضاعة عند اختيار العلاج بدل تجنّب الرعاية."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Notice mood, anxiety, sleep when rest is possible, enjoyment and ability to cope. Ask someone you trust for practical support and contact your care team if symptoms persist, worsen or concern you. You do not need to prove you are struggling enough to deserve help.", "لاحظي المزاج والقلق والنوم عند توفر الراحة والمتعة والقدرة على التكيف. اطلبي دعمًا عمليًا من شخص موثوق وتواصلي مع الفريق إذا استمرت الأعراض أو ساءت أو أقلقتك. لا تحتاجين إثبات شدة المعاناة لاستحقاق المساعدة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask about talking therapies, medicine options and follow-up. Tell the clinician if breastfeeding and about previous mental-health treatment. Urgent thoughts of harm or inability to stay safe require immediate support, not waiting for a routine review. The app does not monitor mood or alert anyone.", "اسألي عن العلاج النفسي والأدوية والمتابعة. اذكري الرضاعة والعلاج النفسي السابق. أفكار الإيذاء العاجلة أو عدم القدرة على البقاء بأمان تستدعي دعمًا فوريًا دون انتظار الموعد الروتيني. التطبيق لا يراقب المزاج ولا ينبه أحدًا."]}]}, "perimenopause": {"understand": ["Changes can involve cycles, temperature regulation, sleep, mood and vaginal comfort. Symptoms vary and can change over time.", "قد تشمل التغيرات الدورة وتنظيم حرارة الجسم والنوم والمزاج وراحة المهبل. تختلف الأعراض وتتبدل مع الوقت."], "assessment": ["Discuss your age, bleeding pattern and symptoms. A clinician considers other explanations and whether tests are useful in your circumstances.", "ناقشي العمر ونمط النزف والأعراض. يقيّم المختص التفسيرات الأخرى ومدى فائدة الفحوص في حالتك."], "options": ["Help is available before periods stop completely. Discuss the symptoms that affect you most, contraception needs and treatment preferences.", "تتوفر المساعدة قبل توقف الدورة تمامًا. ناقشي الأعراض الأشد تأثيرًا واحتياجات منع الحمل وتفضيلات العلاج."], "faq": [["Must I wait until my last period to ask for help?", "هل أنتظر آخر دورة لأطلب المساعدة؟", "No. Troublesome symptoms during the transition also deserve care.", "لا. الأعراض المزعجة خلال المرحلة الانتقالية تستحق الرعاية أيضًا."]], "sources": [["NHS: menopause symptoms", "https://www.nhs.uk/conditions/menopause-and-perimenopause/symptoms/"], ["NHS: treatment choices", "https://www.nhs.uk/conditions/menopause-and-perimenopause/treatment/"]], "questions": [["Could other conditions explain these changes?", "هل تفسّر حالات أخرى هذه التغيرات؟"], ["How can I manage symptoms while considering contraception?", "كيف أتعامل مع الأعراض مع مراعاة منع الحمل؟"]], "related": ["menopause-treatment", "pain-sex", "heavy-periods"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Changes can involve cycles, temperature regulation, sleep, mood and vaginal comfort. Symptoms vary and can change over time.", "قد تشمل التغيرات الدورة وتنظيم حرارة الجسم والنوم والمزاج وراحة المهبل. تختلف الأعراض وتتبدل مع الوقت."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Discuss your age, bleeding pattern and symptoms. A clinician considers other explanations and whether tests are useful in your circumstances.", "ناقشي العمر ونمط النزف والأعراض. يقيّم المختص التفسيرات الأخرى ومدى فائدة الفحوص في حالتك."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Help is available before periods stop completely. Discuss the symptoms that affect you most, contraception needs and treatment preferences.", "تتوفر المساعدة قبل توقف الدورة تمامًا. ناقشي الأعراض الأشد تأثيرًا واحتياجات منع الحمل وتفضيلات العلاج."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Track the changes bothering you most: periods, flushes, sleep, mood or vaginal discomfort. Include their impact at work and home. Symptoms can overlap with other conditions, so do not assume every new problem is menopause. Bring medicines and relevant health history to the discussion.", "تابعي أكثر التغيرات إزعاجًا: الدورة والهبات والنوم والمزاج والانزعاج المهبلي وتأثيرها في العمل والمنزل. قد تتشابه الأعراض مع حالات أخرى؛ لا تفترضي أن كل مشكلة جديدة مرتبطة بانقطاع الطمث. أحضري الأدوية والتاريخ الصحي المهم."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Agree a symptom-management plan and review date. Ask about pregnancy prevention if relevant; symptom treatment and contraception are separate decisions. Report unusual bleeding and ask what changes should prompt reassessment. Your priorities can change and the plan can be revisited.", "اتفقي على خطة للأعراض وموعد مراجعة. اسألي عن منع الحمل عند الحاجة؛ علاج الأعراض ومنع الحمل قراران منفصلان. أبلغي عن النزف غير المعتاد وما يستدعي إعادة التقييم. يمكن تعديل الخطة مع تغير الأولويات."]}]}, "menopause-treatment": {"understand": ["Treatment depends on the symptom, your history and preferences. Systemic hormone therapy and local vaginal treatments have different purposes.", "يعتمد العلاج على العرض وتاريخك وتفضيلاتك. يختلف هدف العلاج الهرموني العام عن العلاجات المهبلية الموضعية."], "assessment": ["Discuss whether you have a womb, your bleeding pattern, medical history and current medicines before choosing hormone treatment.", "ناقشي وجود الرحم ونمط النزف والتاريخ الطبي والأدوية قبل اختيار العلاج الهرموني."], "options": ["Options include hormone therapy, selected non-hormonal medicines and psychological approaches. Systemic oestrogen usually needs womb-lining protection when a womb is present.", "تشمل الخيارات العلاج الهرموني وأدوية غير هرمونية مختارة وأساليب نفسية. يحتاج الإستروجين العام عادةً حماية لبطانة الرحم عند وجوده."], "faq": [["Are herbal treatments automatically safer?", "هل العلاجات العشبية أكثر أمانًا تلقائيًا؟", "No. Evidence, side effects and interactions must also be considered.", "لا. يجب مراعاة الدليل والآثار الجانبية والتداخلات أيضًا."]], "questions": [["What benefits and risks apply to my own health history?", "ما الفوائد والمخاطر المتعلقة بتاريخي الصحي؟"], ["When should treatment be reviewed?", "متى ينبغي مراجعة العلاج؟"]], "related": ["perimenopause", "postmenopausal-bleeding", "bone-health", "pain-sex"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Treatment depends on the symptom, your history and preferences. Systemic hormone therapy and local vaginal treatments have different purposes.", "يعتمد العلاج على العرض وتاريخك وتفضيلاتك. يختلف هدف العلاج الهرموني العام عن العلاجات المهبلية الموضعية."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Discuss whether you have a womb, your bleeding pattern, medical history and current medicines before choosing hormone treatment.", "ناقشي وجود الرحم ونمط النزف والتاريخ الطبي والأدوية قبل اختيار العلاج الهرموني."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Options include hormone therapy, selected non-hormonal medicines and psychological approaches. Systemic oestrogen usually needs womb-lining protection when a womb is present.", "تشمل الخيارات العلاج الهرموني وأدوية غير هرمونية مختارة وأساليب نفسية. يحتاج الإستروجين العام عادةً حماية لبطانة الرحم عند وجوده."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Before choosing treatment, identify what you most want to improve. Ask how systemic HRT, local vaginal treatment and non-hormonal options differ. Tell the prescriber about your uterus, bleeding history, medicines and relevant personal or family illness. There is no single best regimen for everyone.", "حددي أهم ما تريدين تحسينه قبل اختيار العلاج. اسألي عن الفرق بين الهرمونات الجهازية والعلاج المهبلي الموضعي والبدائل غير الهرمونية. اذكري حالة الرحم والنزف والأدوية والأمراض الشخصية والعائلية المهمة. لا يوجد نظام واحد أفضل للجميع."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Ask what benefit to expect, which side effects or bleeding changes to report and when to review. Do not add herbal preparations without discussing interactions. If an option is unsuitable or unwanted, ask about alternatives. The decision can be revisited as symptoms and priorities change.", "اسألي عن الفائدة المتوقعة والآثار أو تغيرات النزف التي تبلغين عنها وموعد المراجعة. لا تضيفي أعشابًا دون مناقشة التداخلات. إذا لم يناسبك خيار أو لم ترغبي به فاسألي عن بدائل. يمكن مراجعة القرار مع تغير الأعراض والأولويات."]}]}, "postmenopausal-bleeding": {"understand": ["Possible causes include fragile tissues, polyps or changes in the womb lining. Cancer is one reason investigation matters, not an automatic diagnosis.", "تشمل الأسباب المحتملة هشاشة الأنسجة واللحميات وتغيرات بطانة الرحم. السرطان سبب لأهمية الفحص، وليس تشخيصًا تلقائيًا."], "assessment": ["Assessment may include examination, vaginal ultrasound, and sometimes hysteroscopy or a sample of the womb lining.", "قد يشمل التقييم الفحص والتصوير المهبلي، وأحيانًا تنظير الرحم أو أخذ عينة من بطانته."], "options": ["Treatment depends on the findings. Tell the team about hormone therapy and any further bleeding while awaiting assessment.", "يعتمد العلاج على النتائج. أبلغي الفريق بالعلاج الهرموني وأي نزف إضافي أثناء انتظار التقييم."], "faq": [["Does one small episode still need checking?", "هل تحتاج بقعة بسيطة مرة واحدة إلى فحص؟", "Yes. Arrange assessment even if the bleeding has stopped.", "نعم. رتّبي التقييم حتى إن توقف النزف."]], "questions": [["Which tests will investigate the womb lining?", "ما الفحوص التي تقيّم بطانة الرحم؟"], ["What should I do if bleeding happens again?", "ماذا أفعل إذا تكرر النزف؟"]], "related": ["menopause-treatment", "examination"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Possible causes include fragile tissues, polyps or changes in the womb lining. Cancer is one reason investigation matters, not an automatic diagnosis.", "تشمل الأسباب المحتملة هشاشة الأنسجة واللحميات وتغيرات بطانة الرحم. السرطان سبب لأهمية الفحص، وليس تشخيصًا تلقائيًا."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Assessment may include examination, vaginal ultrasound, and sometimes hysteroscopy or a sample of the womb lining.", "قد يشمل التقييم الفحص والتصوير المهبلي، وأحيانًا تنظير الرحم أو أخذ عينة من بطانته."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Treatment depends on the findings. Tell the team about hormone therapy and any further bleeding while awaiting assessment.", "يعتمد العلاج على النتائج. أبلغي الفريق بالعلاج الهرموني وأي نزف إضافي أثناء انتظار التقييم."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Arrange assessment even for a single episode or small amount of spotting after menopause. Record the date, amount and associated discomfort, and mention HRT or other medicines. Do not wait to see whether it happens repeatedly before seeking advice.", "رتّبي تقييمًا حتى لنوبة واحدة أو نقاط بسيطة بعد انقطاع الطمث. سجّلي التاريخ والكمية والانزعاج المصاحب واذكري الهرمونات أو الأدوية الأخرى. لا تنتظري تكراره قبل طلب المشورة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["You may be offered an examination, vaginal ultrasound, hysteroscopy or a tissue sample depending on findings. Ask how to prepare and how discomfort will be managed. Confirm who explains results and what to do if bleeding returns after an initial reassuring assessment.", "قد يُعرض فحص أو تصوير مهبلي أو منظار رحم أو عينة بحسب النتائج. اسألي عن الاستعداد والتعامل مع الانزعاج. حددي من يشرح النتائج وما العمل إذا عاد النزف بعد تقييم مطمئن مبدئيًا."]}]}, "bone-health": {"understand": ["Bone weakness can remain unnoticed until a fracture. Early menopause, some medicines and family history can increase risk.", "قد لا تُلاحظ هشاشة العظام حتى يحدث كسر. قد يزيد الخطر مع الانقطاع المبكر وبعض الأدوية والتاريخ العائلي."], "assessment": ["A clinician may assess fracture risk and request a bone-density scan. Decisions use your overall risk, not age alone.", "قد يقيّم المختص خطر الكسور ويطلب فحص كثافة العظام. تعتمد القرارات على الخطر الكلي لا العمر وحده."], "options": ["Discuss suitable activity, nutrition, fall prevention and whether bone-strengthening medicines are needed. Supplements are not the whole treatment plan.", "ناقشي النشاط والتغذية المناسبين والوقاية من السقوط والحاجة لأدوية تقوية العظام. المكمّلات ليست الخطة العلاجية بأكملها."], "faq": [["Is a previous low-impact fracture worth mentioning?", "هل من المهم ذكر كسر سابق بعد إصابة بسيطة؟", "Yes. Previous fractures can change risk assessment and treatment decisions.", "نعم. قد تغيّر الكسور السابقة تقييم الخطر وقرارات العلاج."]], "questions": [["Do I need a bone-density scan or fracture-risk assessment?", "هل أحتاج فحص كثافة العظام أو تقييم خطر الكسور؟"], ["Which exercise is safe for my current bone health?", "ما التمارين الآمنة لحالة عظامي؟"]], "related": ["perimenopause", "menopause-treatment"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["Bone weakness can remain unnoticed until a fracture. Early menopause, some medicines and family history can increase risk.", "قد لا تُلاحظ هشاشة العظام حتى يحدث كسر. قد يزيد الخطر مع الانقطاع المبكر وبعض الأدوية والتاريخ العائلي."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["A clinician may assess fracture risk and request a bone-density scan. Decisions use your overall risk, not age alone.", "قد يقيّم المختص خطر الكسور ويطلب فحص كثافة العظام. تعتمد القرارات على الخطر الكلي لا العمر وحده."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Discuss suitable activity, nutrition, fall prevention and whether bone-strengthening medicines are needed. Supplements are not the whole treatment plan.", "ناقشي النشاط والتغذية المناسبين والوقاية من السقوط والحاجة لأدوية تقوية العظام. المكمّلات ليست الخطة العلاجية بأكملها."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Ask about bone health if you have relevant risk factors or a low-trauma fracture. Weight-bearing and resistance activity suited to your ability, adequate nutrition and reducing falls can support bone health. Ask for advice if pain, balance problems or another condition limits exercise.", "اسألي عن صحة العظام عند عوامل خطر أو كسر بعد إصابة بسيطة. قد يدعمها نشاط تحميل الوزن والمقاومة الملائم والتغذية الكافية وتقليل السقوط. اطلبي المشورة إذا حد الألم أو خلل التوازن أو مرض آخر من الرياضة."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["If a bone-density scan or medicine is suggested, ask what the result means for your fracture risk and how follow-up works. Discuss calcium and vitamin D needs individually. Do not assume a supplement alone replaces assessment or a prescribed treatment plan.", "إذا اقتُرح قياس كثافة العظام أو دواء فاسألي عن معنى النتيجة لخطر الكسر والمتابعة. ناقشي الاحتياج للكالسيوم وفيتامين د فرديًا. لا تفترضي أن المكمل وحده يغني عن التقييم أو العلاج الموصوف."]}]}, "examination": {"understand": ["An explanation should cover the purpose, benefits, risks and alternatives. Consent should be informed and voluntary, with local legal arrangements considered.", "ينبغي أن يشمل الشرح الهدف والفوائد والمخاطر والبدائل. يجب أن تكون الموافقة مستنيرة وطوعية مع مراعاة الترتيبات القانونية المحلية."], "assessment": ["Ask what will happen before each step. Explain language, mobility, pain or anxiety needs and ask what support is available.", "اسألي عما سيحدث قبل كل خطوة. اشرحي احتياجات اللغة أو الحركة أو الألم أو القلق واسألي عن الدعم المتاح."], "options": ["Discuss alternatives and what happens if a procedure is delayed or declined. Tell the clinician when you need to pause.", "ناقشي البدائل وما يحدث إن تأجل الإجراء أو رفضته. أخبري المختص عند حاجتك إلى التوقف."], "faq": [["Is signing a form the whole consent process?", "هل توقيع الاستمارة هو كل عملية الموافقة؟", "No. Understanding the proposed care and having your questions answered matter.", "لا. فهم الرعاية المقترحة والإجابة عن أسئلتك جزء مهم."]], "questions": [["What alternatives do I have and what happens if I wait?", "ما البدائل وما الذي يحدث إذا انتظرت؟"], ["Can we agree how I can ask you to pause?", "هل نتفق على طريقة أطلب بها التوقف؟"]], "related": ["screening", "pain-sex", "breast"], "sections": [{"title": ["Understand the concern", "فهم المشكلة"], "text": ["An explanation should cover the purpose, benefits, risks and alternatives. Consent should be informed and voluntary, with local legal arrangements considered.", "ينبغي أن يشمل الشرح الهدف والفوائد والمخاطر والبدائل. يجب أن تكون الموافقة مستنيرة وطوعية مع مراعاة الترتيبات القانونية المحلية."]}, {"title": ["What assessment may involve", "ما الذي قد يشمله التقييم؟"], "text": ["Ask what will happen before each step. Explain language, mobility, pain or anxiety needs and ask what support is available.", "اسألي عما سيحدث قبل كل خطوة. اشرحي احتياجات اللغة أو الحركة أو الألم أو القلق واسألي عن الدعم المتاح."]}, {"title": ["Care options to discuss", "خيارات الرعاية للمناقشة"], "text": ["Discuss alternatives and what happens if a procedure is delayed or declined. Tell the clinician when you need to pause.", "ناقشي البدائل وما يحدث إن تأجل الإجراء أو رفضته. أخبري المختص عند حاجتك إلى التوقف."]}, {"title": ["Practical next steps", "خطوات عملية تالية"], "text": ["Ask why the examination is recommended, what it involves and whether alternatives exist. You can request an interpreter, a chaperone and time to ask questions. Tell the clinician about pain, past difficult experiences or adjustments that would help; you decide what you wish to disclose.", "اسألي عن سبب الفحص وخطواته والبدائل. يمكنك طلب مترجم ومرافق مهني ووقت للأسئلة. اذكري الألم أو التجارب الصعبة أو التعديلات المفيدة؛ أنت تقررين ما ترغبين في الإفصاح عنه."]}, {"title": ["Follow-up and decisions", "المتابعة والقرارات"], "text": ["Consent is a conversation, not just a signature. Ask to pause if you need an explanation or are uncomfortable. Afterwards, ask what was found, what samples were taken and when results will arrive. If something remains unclear, request a written explanation or another discussion.", "الموافقة حوار وليست توقيعًا فقط. اطلبي التوقف للشرح أو عند الانزعاج. اسألي بعد الفحص عما وُجد والعينات المأخوذة وموعد النتائج. إذا بقي شيء غير واضح فاطلبي شرحًا مكتوبًا أو مناقشة أخرى."]}]}};
const newGuides = [{"id": "fertility-assessment", "title": ["When pregnancy is not happening", "عندما يتأخر حدوث الحمل"], "body": ["Fertility difficulties can involve either partner, both partners, or an unexplained cause. They are not a personal failure. Assessment should consider the whole situation.", "قد ترتبط صعوبات الإنجاب بأي من الشريكين أو كليهما أو بسبب غير مفسّر. ليست فشلًا شخصيًا، ويجب أن ينظر التقييم إلى الصورة كاملة."], "track": ["Bring cycle dates, time trying, previous pregnancies, operations, medicines and any previous test results.", "أحضري تواريخ الدورة ومدة المحاولة والحمل السابق والعمليات والأدوية ونتائج الفحوص السابقة."], "help": ["Seek advice after a year of trying, or earlier with increasing age, irregular periods, known reproductive conditions or previous cancer treatment. Local referral criteria vary.", "اطلبي المشورة بعد سنة من المحاولة، وأبكر مع التقدم بالعمر أو اضطراب الدورة أو مرض تناسلي معروف أو علاج سابق للسرطان. تختلف معايير الإحالة محليًا."], "url": "https://www.who.int/news-room/fact-sheets/detail/infertility", "understand": ["A previous pregnancy does not rule out a later fertility problem. An app estimate of ovulation cannot confirm whether ovulation or conception is occurring.", "لا يستبعد الحمل السابق مشكلة خصوبة لاحقة. ولا يؤكد تقدير التطبيق للإباضة حدوثها أو حدوث الإخصاب."], "assessment": ["Tests may assess ovulation, the womb and tubes, and semen where relevant. Not everyone needs every test; hormone-test timing depends on the question being asked.", "قد تقيّم الفحوص الإباضة والرحم والأنابيب والسائل المنوي عند الحاجة. لا يحتاج الجميع إلى كل فحص، ويتوقف توقيت تحليل الهرمونات على هدفه."], "options": ["Agree the next investigation, how results will be explained and when treatment options will be discussed. Ask about emotional support and local costs before committing to a programme.", "اتّفقي على الفحص التالي وكيفية شرح النتائج وموعد مناقشة خيارات العلاج. اسألي عن الدعم النفسي والتكاليف المحلية قبل الالتزام ببرنامج."], "faq": [["Is fertility assessment only for the woman?", "هل تقييم الخصوبة للمرأة فقط؟", "No. Assessment should include the relevant reproductive factors of both partners when applicable.", "لا. ينبغي أن يشمل العوامل التناسلية ذات الصلة لدى الشريكين عند انطباق ذلك."]], "questions": [["Do I need assessment now rather than waiting?", "هل أحتاج التقييم الآن بدل الانتظار؟"], ["Which tests should each of us have, and why?", "ما الفحوص اللازمة لكل منا ولماذا؟"]], "related": ["pcos", "endometriosis", "pregnancy-conditions"], "sources": [["WHO: infertility", "https://www.who.int/news-room/fact-sheets/detail/infertility"], ["NHS: fertility assessment", "https://www.nhs.uk/conditions/infertility/diagnosis/"]], "chapters": ["planning"]}, {"id": "pregnancy-conditions", "title": ["Pregnancy with a long-term condition", "الحمل مع مرض مزمن"], "body": ["Diabetes, hypertension, epilepsy, heart disease and other conditions can change pregnancy planning. A coordinated plan should consider both the condition and its treatment.", "قد يؤثر السكري وارتفاع الضغط والصرع وأمراض القلب وغيرها في التخطيط للحمل. يجب أن تراعي الخطة المنسقة المرض وعلاجه معًا."], "track": ["Prepare diagnosis details, specialist contacts, medicine names and doses, supplements and recent results.", "جهّزي تفاصيل التشخيص ووسائل التواصل مع المختصين وأسماء الأدوية وجرعاتها والمكمّلات والنتائج الحديثة."], "help": ["Request a pre-pregnancy review if possible, or contact your team promptly when pregnancy is discovered. Do not stop prescribed treatment on your own.", "اطلبي مراجعة قبل الحمل إن أمكن، أو تواصلي سريعًا مع فريقك عند اكتشافه. لا توقفي العلاج الموصوف بنفسك."], "url": "https://www.nhs.uk/pregnancy/keeping-well/medicines/", "understand": ["A medicine decision balances treatment benefits, the effects of uncontrolled illness and possible pregnancy risks. Selecting a disease in this prototype does not perform that assessment.", "يوازن قرار الدواء بين فائدته وتأثير المرض غير المضبوط ومخاطر الحمل المحتملة. اختيار مرض في النموذج لا يجري هذا التقييم."], "assessment": ["Your usual specialist and maternity team may need to coordinate. Ask who reviews medicines, who orders monitoring and who to contact between visits.", "قد يحتاج مختصك المعتاد وفريق الولادة إلى التنسيق. اسألي من يراجع الأدوية ومن يطلب المتابعة وبمن تتواصلين بين الزيارات."], "options": ["The plan may involve treatment adjustments and additional checks. Take over-the-counter and herbal products into the same review; natural does not automatically mean suitable.", "قد تشمل الخطة تعديل العلاج وفحوصًا إضافية. أدرجي الأدوية دون وصفة والمنتجات العشبية في المراجعة؛ الطبيعي ليس مناسبًا تلقائيًا."], "faq": [["Is stopping everything the safest choice?", "هل إيقاف كل الأدوية هو الخيار الأكثر أمانًا؟", "No. Stopping necessary treatment can harm you and the pregnancy. Get individual advice promptly.", "لا. قد يضر إيقاف العلاج الضروري بك وبالحمل. اطلبي نصيحة فردية سريعًا."]], "questions": [["What should change before conception or now that I am pregnant?", "ما الذي ينبغي تغييره قبل الإخصاب أو الآن بعد الحمل؟"], ["Who coordinates my condition and pregnancy follow-up?", "من ينسّق متابعة مرضي وحملي؟"]], "related": ["maternal-warning", "fertility-assessment"], "sources": [["NHS: medicines in pregnancy", "https://www.nhs.uk/pregnancy/keeping-well/medicines/"], ["Salisbury NHS: existing conditions", "https://www.salisbury.nhs.uk/wards-departments/departments/maternity/planning-for-pregnancy/existing-health-conditions/"]], "chapters": ["planning", "expecting"]}, {"id": "feeding-problems", "title": ["Painful feeding, milk concerns & mastitis", "ألم الرضاعة ومخاوف الحليب والتهاب الثدي"], "body": ["Feeding difficulties deserve practical help. Persistent nipple pain, uncomfortable fullness or worries about milk transfer are reasons to ask someone qualified to observe a feed.", "تستحق صعوبات الرضاعة مساعدة عملية. ألم الحلمة المستمر أو الامتلاء المزعج أو القلق بشأن انتقال الحليب أسباب لطلب مشاهدة الرضعة من مختص."], "track": ["Record when pain occurs, breast changes and feeding concerns. Ask for assessment of your baby as well as you.", "دوّني توقيت الألم وتغيرات الثدي ومخاوف التغذية. اطلبي تقييم طفلك أيضًا إلى جانب تقييمك."], "help": ["Seek care if breast pain persists, symptoms worsen or you feel unwell. Mastitis not improving within 12–24 hours needs medical advice.", "اطلبي الرعاية مع ألم الثدي المستمر أو تدهور الأعراض أو الشعور بالمرض. عدم تحسن التهاب الثدي خلال ١٢–٢٤ ساعة يحتاج مشورة طبية."], "url": "https://www.nhs.uk/baby/breastfeeding-and-bottle-feeding/breastfeeding-problems/common-problems/", "understand": ["Attachment problems, engorgement and inflammation can cause pain. Not every painful nipple is a fungal infection; repeated treatment without assessment may miss the cause.", "قد تسبب مشكلات الالتقام والاحتقان والالتهاب الألم. ليست كل حلمة مؤلمة مصابة بالفطريات؛ وقد يفوّت تكرار العلاج دون تقييم السبب."], "assessment": ["A feeding professional can assess positioning, attachment and milk transfer. A hot painful breast, a lump or systemic symptoms may need a clinical examination.", "يمكن لمختص الرضاعة تقييم الوضعية والالتقام وانتقال الحليب. وقد يحتاج الثدي الساخن المؤلم أو الكتلة أو الأعراض العامة إلى فحص طبي."], "options": ["With mastitis, avoid forceful massage and expressing more than the baby needs. Feeding can usually continue; get an individual plan if it is too painful. Some cases need antibiotics or further treatment.", "مع التهاب الثدي تجنّبي التدليك القوي وشفط أكثر من حاجة الطفل. يمكن عادةً الاستمرار بالرضاعة؛ اطلبي خطة فردية إن كانت شديدة الألم. تحتاج بعض الحالات مضادات أو علاجًا إضافيًا."], "faq": [["Should I suddenly stop breastfeeding for mastitis?", "هل أوقف الرضاعة فجأة بسبب الالتهاب؟", "Usually no. Seek advice on comfortable feeding or expression rather than stopping abruptly.", "عادةً لا. اطلبي نصيحة بشأن الرضاعة أو إخراج الحليب براحة بدل التوقف المفاجئ."]], "questions": [["Can you observe a feed and check milk transfer?", "هل يمكنك مشاهدة رضعة وتقييم انتقال الحليب؟"], ["What should prompt another review?", "ما الذي يستدعي مراجعة أخرى؟"]], "related": ["breast", "postnatal-mood", "maternal-warning"], "sources": [["NHS: feeding difficulties", "https://www.nhs.uk/baby/breastfeeding-and-bottle-feeding/breastfeeding-problems/common-problems/"], ["NHS: mastitis", "https://www.nhs.uk/conditions/mastitis/"]], "chapters": ["after", "body"]}, {"id": "pain-sex", "title": ["Pain during sex & vaginal dryness", "الألم أثناء الجماع وجفاف المهبل"], "body": ["Pain is a reason to pause, not something to push through. Dryness, infection, skin problems, pelvic conditions or involuntary muscle tightening may contribute.", "الألم سبب للتوقف، وليس أمرًا ينبغي تحمّله. قد تسهم فيه قلة الترطيب أو العدوى أو مشكلات الجلد أو الحوض أو تقلص العضلات اللاإرادي."], "track": ["Note whether pain is at the entrance or deeper, when it began, and any dryness, discharge or bleeding.", "دوّني هل الألم عند المدخل أم أعمق، ومتى بدأ، وأي جفاف أو إفرازات أو نزف."], "help": ["Arrange assessment for persistent pain, unusual discharge or bleeding after sex. Sudden severe pelvic pain needs urgent assessment.", "رتّبي التقييم للألم المستمر أو الإفرازات غير المعتادة أو النزف بعد الجماع. يحتاج ألم الحوض المفاجئ الشديد إلى تقييم عاجل."], "url": "https://www.nhs.uk/symptoms/vaginal-dryness/", "understand": ["Dryness may occur with breastfeeding, menopause, some medicines or irritation. Vaginismus involves automatic muscle tightening; it is not a deliberate refusal or failure.", "قد يحدث الجفاف مع الرضاعة أو انقطاع الطمث أو بعض الأدوية أو التهيّج. يتضمن التشنج المهبلي انقباضًا تلقائيًا، وليس رفضًا متعمدًا أو فشلًا."], "assessment": ["A clinician can discuss symptoms before offering an examination. Explain what feels uncomfortable and agree how to pause. Testing depends on the possible cause.", "يمكن مناقشة الأعراض قبل اقتراح الفحص. اشرحي ما يزعجك واتّفقي على طريقة للتوقف. تتحدد الفحوص بحسب السبب المحتمل."], "options": ["Vaginal moisturisers or water-based lubricants may help dryness. Other causes may need targeted treatment, pelvic-health therapy or psychosexual support. Hormonal options need individual assessment.", "قد تفيد المرطّبات المهبلية أو المزلّقات المائية للجفاف. وقد تحتاج أسباب أخرى علاجًا موجّهًا أو علاج قاع الحوض أو دعمًا نفسيًا جنسيًا. تحتاج الخيارات الهرمونية تقييمًا فرديًا."], "faq": [["Is this only a problem after menopause?", "هل تحدث هذه المشكلة فقط بعد انقطاع الطمث؟", "No. Pain and dryness can happen at different ages and life stages.", "لا. قد يحدث الألم والجفاف في أعمار ومراحل مختلفة."]], "questions": [["What causes should be considered for my type of pain?", "ما الأسباب التي ينبغي التفكير فيها لنوع ألمي؟"], ["Could pelvic-health or psychosexual therapy help?", "هل قد يفيد علاج قاع الحوض أو الدعم النفسي الجنسي؟"]], "related": ["discharge", "endometriosis", "menopause-treatment", "examination"], "sources": [["NHS: vaginal dryness", "https://www.nhs.uk/symptoms/vaginal-dryness/"], ["NHS: vaginismus", "https://www.nhs.uk/conditions/vaginismus/"]], "chapters": ["sexual", "after", "later"]}, {"id": "maternal-warning", "title": ["Urgent symptoms in pregnancy & after birth", "الأعراض العاجلة أثناء الحمل وبعد الولادة"], "body": ["Serious pregnancy-related problems can occur during pregnancy and up to a year afterwards. Tell the care team about recent pregnancy.", "قد تحدث مشكلات خطرة مرتبطة بالحمل أثناءه وحتى سنة بعده. أخبري فريق الرعاية بالحمل الحديث."], "track": ["Tell the team what changed and when.", "أخبري الفريق بما تغيّر ومتى."], "help": ["Get immediate medical help for chest pain, difficulty breathing, collapse, severe persistent headache or abdominal pain, heavy bleeding, or danger of harming yourself or your baby.", "اطلبي مساعدة طبية فورًا لألم الصدر أو صعوبة التنفس أو الانهيار أو صداع أو ألم بطن شديد مستمر أو نزف غزير أو خطر إيذاء نفسك أو طفلك."], "url": "https://www.cdc.gov/hearher/maternal-warning-signs/index.html", "understand": ["Other warning signs include vision changes, fever, one-sided limb swelling, leaking fluid or reduced fetal movement.", "تشمل علامات أخرى تغير الرؤية والحمى وتورم طرف واحد وتسرب السائل أو نقص حركة الجنين."], "assessment": ["These symptoms need professional assessment, not a reassuring app result.", "تحتاج هذه الأعراض تقييمًا مهنيًا، وليس نتيجة مطمئنة من تطبيق."], "options": ["Contact emergency or maternity care now. If you cannot reach your team, seek emergency care.", "تواصلي الآن مع الطوارئ أو قسم الولادة. إذا تعذر الوصول لفريقك فاطلبي رعاية الطوارئ."], "faq": [["Can I wait for the next appointment?", "هل أنتظر الموعد المقبل؟", "Do not delay urgent assessment.", "لا تؤخري التقييم العاجل."]], "questions": [["Who should I call urgently during pregnancy and after birth?", "بمن أتصل عاجلًا أثناء الحمل وبعد الولادة؟"]], "related": ["ectopic", "labour", "postnatal-mood"], "sources": [["CDC: urgent maternal warning signs", "https://www.cdc.gov/hearher/maternal-warning-signs/index.html"]], "chapters": ["expecting", "after", "birth"]}, {"id": "bloating", "title": ["Persistent bloating & ovarian cancer concerns", "الانتفاخ المستمر ومخاوف سرطان المبيض"], "body": ["Bloating is common and often has non-cancer causes. New, frequent or persistent bloating deserves attention, especially with pelvic pain, early fullness or urinary changes.", "الانتفاخ شائع وله غالبًا أسباب غير سرطانية. يستحق الانتفاخ الجديد المتكرر أو المستمر الاهتمام، خصوصًا مع ألم الحوض أو الشبع المبكر أو تغير التبول."], "track": ["Record frequency, appetite changes, pain and any family history of ovarian or breast cancer.", "دوّني التكرار وتغير الشهية والألم وأي تاريخ عائلي لسرطان المبيض أو الثدي."], "help": ["Arrange assessment for persistent symptoms. Return if symptoms continue, worsen or become more frequent after an initial review.", "رتّبي التقييم للأعراض المستمرة. عودي إذا استمرت الأعراض أو ساءت أو زاد تكرارها بعد المراجعة الأولى."], "url": "https://www.nhs.uk/conditions/ovarian-cancer/symptoms/", "understand": ["These symptoms do not diagnose cancer. Their persistence and change from your usual pattern help decide what investigation is needed.", "لا تشخّص هذه الأعراض السرطان. يساعد استمرارها وتغيّرها عن المعتاد في تحديد الفحوص اللازمة."], "assessment": ["A clinician may examine you and arrange a blood test or ultrasound. Further tests may be needed to confirm a suspected diagnosis.", "قد يفحصك المختص ويطلب تحليل دم أو تصويرًا بالموجات الصوتية. وقد تلزم فحوص إضافية لتأكيد تشخيص مشتبه به."], "options": ["Ask who will explain results and the plan if symptoms remain unexplained. A normal initial scan does not mean persistent symptoms should be ignored.", "اسألي من يشرح النتائج وما الخطة إذا بقي السبب مجهولًا. لا تعني صورة أولية طبيعية تجاهل الأعراض المستمرة."], "faq": [["Does referral to a cancer specialist prove I have cancer?", "هل تثبت الإحالة لمختص أورام أن لدي سرطانًا؟", "No. Referral is a way to investigate a concern, not a confirmed diagnosis.", "لا. الإحالة وسيلة لفحص القلق، وليست تشخيصًا مؤكدًا."]], "questions": [["What follow-up is needed if my tests are reassuring but symptoms continue?", "ما المتابعة إذا كانت الفحوص مطمئنة لكن الأعراض مستمرة؟"], ["Does my family history change the assessment?", "هل يغيّر تاريخي العائلي التقييم؟"]], "related": ["cysts", "fibroids", "postmenopausal-bleeding"], "sources": [["NHS: ovarian cancer symptoms", "https://www.nhs.uk/conditions/ovarian-cancer/symptoms/"], ["NHS: tests and next steps", "https://www.nhs.uk/conditions/ovarian-cancer/tests-and-next-steps/"]], "chapters": ["gyn", "later", "prevention"]}, {"id": "period-care", "title": ["Periods, pain & bleeding: a practical pathway", "الدورة والألم والنزف: خطوات عملية"], "chapters": ["growing", "periods", "gyn"], "related": ["first-period", "period-pain", "heavy-periods", "endometriosis", "missed-periods"], "sources": [["NHS: periods", "https://www.nhs.uk/conditions/periods/"], ["NHS: period pain", "https://www.nhs.uk/symptoms/period-pain/"], ["NHS: heavy periods", "https://www.nhs.uk/conditions/heavy-periods/"], ["NHS: endometriosis", "https://www.nhs.uk/conditions/endometriosis/"]], "sections": [{"title": ["Start with your own pattern", "ابدئي بنمط دورتك"], "text": ["Record the first day of bleeding, duration, leaking through clothes, pain, and missed school or work. The impact on your life matters; you do not need to measure blood in millilitres. Note bleeding between periods or after sex separately. A diary supports a conversation but cannot identify the cause.", "دوّني أول يوم للنزف ومدته والتسرب للملابس والألم والغياب عن الدراسة أو العمل. تأثير الأعراض في حياتك مهم؛ لا تحتاجين قياس الدم بالملليلتر. سجّلي النزف بين الدورات أو بعد الجماع بشكل منفصل. يساعد السجل في الحوار لكنه لا يشخّص السبب."]}, {"title": ["What can I do today?", "ماذا أفعل اليوم؟"], "text": ["For familiar period cramps, try gentle movement or a warm bath. Wrap a heat pack to protect the skin. Choose period products you can use comfortably and follow their cleaning and changing instructions. Ask a pharmacist whether pain relief is appropriate for your health and medicines. Severe or worsening pain needs assessment rather than repeated self-treatment.", "للتقلصات المعتادة جرّبي حركة لطيفة أو حمامًا دافئًا. غلّفي الكمادة لحماية الجلد. اختاري منتجات مريحة للدورة واتبعي تعليمات تغييرها وتنظيفها. اسألي الصيدلي عن ملاءمة المسكن لحالتك وأدويتك. الألم الشديد أو المتفاقم يحتاج تقييمًا بدل تكرار العلاج الذاتي."]}, {"title": ["What might an appointment involve?", "ماذا قد يشمل الموعد؟"], "text": ["A clinician may discuss pregnancy possibility, medicines, bleeding and pain patterns. Heavy bleeding may prompt blood tests for anaemia. Examination or ultrasound depends on the history. Pain with sex, bowel movements or urination is useful to mention. Endometriosis assessment may require specialist imaging or laparoscopy; discuss why each test is being considered.", "قد يناقش المختص احتمال الحمل والأدوية ونمط النزف والألم. قد يستدعي النزف الغزير تحليلًا لفقر الدم. يعتمد الفحص أو التصوير على التاريخ المرضي. اذكري الألم مع الجماع أو التبرز أو التبول. قد يتطلب تقييم الانتباذ البطاني تصويرًا متخصصًا أو منظارًا؛ اسألي عن سبب كل فحص."]}, {"title": ["Understanding the choices", "فهم الخيارات"], "text": ["For heavy bleeding, options may include bleeding-reduction medicines, hormonal methods or procedures. For suspected endometriosis, pain treatment, hormones and surgery have different purposes and trade-offs. Tell the team whether you want pregnancy now or later. Ask what improvement to expect and when to return if treatment does not help. A treatment decision is not a permanent commitment.", "قد تشمل خيارات النزف الغزير أدوية لتقليل النزف أو وسائل هرمونية أو إجراءات. وللاشتباه بالانتباذ البطاني تختلف أهداف وموازنة المسكنات والهرمونات والجراحة. أخبري الفريق برغبتك في الحمل الآن أو لاحقًا. اسألي عن التحسن المتوقع وموعد العودة إن لم يتحسن الوضع. القرار العلاجي قابل للمراجعة."]}, {"title": ["Your next step", "خطوتك التالية"], "text": ["Choose one concern to bring to an appointment: pain, bleeding, or cycle change. Take your diary and list the treatments already tried, including whether they helped. Ask for a clear follow-up plan and who will explain test results. You can request an explanation and pause an examination.", "اختاري أهم ما يقلقك للموعد: الألم أو النزف أو تغيّر الدورة. أحضري السجل والعلاجات التي جرّبتِها ومدى فائدتها. اطلبي خطة متابعة واضحة وحددي من يشرح النتائج. يمكنك طلب شرح الفحص والتوقف أثناءه."]}], "body": ["A step-by-step guide to understanding your concern, preparing for care and following up.", "دليل خطوة بخطوة لفهم مخاوفك والاستعداد للرعاية والمتابعة."], "track": ["Write down your priority, what you have already tried and the questions you want answered.", "دوّني أولويتك وما جرّبتِه والأسئلة التي تريدين الإجابة عنها."], "help": ["Use the urgent-help link for urgent symptoms. This pathway does not assess your symptoms.", "استخدمي رابط المساعدة العاجلة للأعراض العاجلة. هذا المسار لا يقيّم أعراضك."], "url": "https://www.nhs.uk/conditions/periods/", "understand": ["Record the first day of bleeding, duration, leaking through clothes, pain, and missed school or work. The impact on your life matters; you do not need to measure blood in millilitres. Note bleeding between periods or after sex separately. A diary supports a conversation but cannot identify the cause.", "دوّني أول يوم للنزف ومدته والتسرب للملابس والألم والغياب عن الدراسة أو العمل. تأثير الأعراض في حياتك مهم؛ لا تحتاجين قياس الدم بالملليلتر. سجّلي النزف بين الدورات أو بعد الجماع بشكل منفصل. يساعد السجل في الحوار لكنه لا يشخّص السبب."], "assessment": ["A clinician may discuss pregnancy possibility, medicines, bleeding and pain patterns. Heavy bleeding may prompt blood tests for anaemia. Examination or ultrasound depends on the history. Pain with sex, bowel movements or urination is useful to mention. Endometriosis assessment may require specialist imaging or laparoscopy; discuss why each test is being considered.", "قد يناقش المختص احتمال الحمل والأدوية ونمط النزف والألم. قد يستدعي النزف الغزير تحليلًا لفقر الدم. يعتمد الفحص أو التصوير على التاريخ المرضي. اذكري الألم مع الجماع أو التبرز أو التبول. قد يتطلب تقييم الانتباذ البطاني تصويرًا متخصصًا أو منظارًا؛ اسألي عن سبب كل فحص."], "options": ["For heavy bleeding, options may include bleeding-reduction medicines, hormonal methods or procedures. For suspected endometriosis, pain treatment, hormones and surgery have different purposes and trade-offs. Tell the team whether you want pregnancy now or later. Ask what improvement to expect and when to return if treatment does not help. A treatment decision is not a permanent commitment.", "قد تشمل خيارات النزف الغزير أدوية لتقليل النزف أو وسائل هرمونية أو إجراءات. وللاشتباه بالانتباذ البطاني تختلف أهداف وموازنة المسكنات والهرمونات والجراحة. أخبري الفريق برغبتك في الحمل الآن أو لاحقًا. اسألي عن التحسن المتوقع وموعد العودة إن لم يتحسن الوضع. القرار العلاجي قابل للمراجعة."], "faq": [["What if I still need help?", "ماذا إن احتجت مساعدة إضافية؟", "Arrange follow-up and ask who is responsible for reviewing results and next steps.", "رتّبي متابعة واسألي من يراجع النتائج والخطوات التالية."]], "questions": [["What should improve, and when should I return if it does not?", "ما التحسن المتوقع ومتى أعود إن لم يحدث؟"], ["Who will explain my results and arrange the next step?", "من يشرح نتائجي ويرتّب الخطوة التالية؟"]]}, {"id": "prepare-care", "title": ["Preparing for pregnancy & fertility assessment", "الاستعداد للحمل وتقييم الخصوبة"], "chapters": ["planning"], "related": ["pregnancy-conditions", "fertility-assessment", "pcos", "endometriosis"], "sources": [["NHS: trying to get pregnant", "https://www.nhs.uk/pregnancy/trying-for-a-baby/trying-to-get-pregnant/"], ["NHS: infertility assessment", "https://www.nhs.uk/conditions/infertility/diagnosis/"], ["WHO: infertility", "https://www.who.int/news-room/fact-sheets/detail/infertility"]], "sections": [{"title": ["Before you start trying", "قبل محاولة الحمل"], "text": ["Make a list of prescriptions, non-prescription medicines and supplements. Arrange a pre-pregnancy review for long-term conditions or previous pregnancy complications. Ask about vaccinations, screening and suitable folic acid. Do not stop prescribed treatment yourself. Support with smoking, alcohol, nutrition and mental wellbeing belongs in preparation too.", "اكتبي قائمة الوصفات والأدوية دون وصفة والمكملات. رتّبي مراجعة قبل الحمل للأمراض المزمنة أو مضاعفات حمل سابقة. اسألي عن اللقاحات والتحري وحمض الفوليك المناسب. لا توقفي العلاج الموصوف بنفسك. يشمل الاستعداد دعم الإقلاع عن التدخين والكحول والتغذية والصحة النفسية."]}, {"title": ["Trying without turning life into a test", "المحاولة دون تحويل الحياة إلى اختبار"], "text": ["If pregnancy through intercourse is your plan, sex every two to three days is one practical approach described by NHS guidance. A calendar cannot confirm ovulation. If intercourse is painful or difficult, seek help rather than forcing it. Fertility concerns can affect relationships and wellbeing; either partner may need support.", "إذا كان الحمل عبر الجماع هو خطتك، فالجماع كل يومين إلى ثلاثة نهج عملي تذكره إرشادات NHS. لا يؤكد التقويم حدوث الإباضة. إذا كان الجماع مؤلمًا أو صعبًا، اطلبي المساعدة ولا تضغطي على نفسك. قد تؤثر مخاوف الخصوبة في العلاقة والصحة النفسية ويحتاج أي شريك للدعم."]}, {"title": ["When to request assessment", "متى أطلب التقييم؟"], "text": ["Request assessment after a year of trying without pregnancy, or earlier when age, irregular cycles, a known condition or previous treatment may affect fertility. Do not assume the cause lies with one partner. Local eligibility, funding and referral arrangements differ; ask the service what applies to your situation.", "اطلبي التقييم بعد سنة من المحاولة دون حمل، أو أبكر إذا كان العمر أو عدم انتظام الدورة أو مرض معروف أو علاج سابق قد يؤثر في الخصوبة. لا تفترضي أن السبب لدى شريك واحد. تختلف شروط الخدمة والتمويل والإحالة محليًا؛ اسألي عمّا ينطبق على حالتك."]}, {"title": ["What tests and treatment can mean", "ماذا تعني الفحوص والعلاج؟"], "text": ["Assessment may include a cycle and pregnancy history, ovulation-related blood tests, ultrasound, tests of the fallopian tubes and semen analysis. Not everyone needs every test. Ask what each result changes. Treatment depends on the cause and preferences; an assessment does not automatically mean IVF. Ask about alternatives, costs and realistic expectations before committing.", "قد يشمل التقييم تاريخ الدورة والحمل وتحاليل مرتبطة بالإباضة والتصوير وفحص الأنابيب وتحليل السائل المنوي. لا يحتاج الجميع لكل الفحوص. اسألي كيف تغيّر النتيجة الخطة. يعتمد العلاج على السبب والتفضيلات ولا يعني التقييم تلقائيًا أطفال الأنابيب. اسألي عن البدائل والتكلفة والتوقعات الواقعية قبل القرار."]}, {"title": ["Make the next visit useful", "اجعلي الموعد القادم مفيدًا"], "text": ["Bring previous results so tests are not repeated unnecessarily. Write down what you want to understand: whether further testing is needed, which choices are available, or when to reassess. Keep copies of the plan and ask how to get results. You may request time to consider choices and emotional support.", "أحضري النتائج السابقة لتجنب التكرار غير الضروري. دوّني ما تريدين فهمه: الحاجة لفحوص أخرى أو الخيارات أو موعد إعادة التقييم. احتفظي بالخطة واسألي كيف تحصلين على النتائج. يمكنك طلب وقت للتفكير ودعم نفسي."]}], "body": ["A step-by-step guide to understanding your concern, preparing for care and following up.", "دليل خطوة بخطوة لفهم مخاوفك والاستعداد للرعاية والمتابعة."], "track": ["Write down your priority, what you have already tried and the questions you want answered.", "دوّني أولويتك وما جرّبتِه والأسئلة التي تريدين الإجابة عنها."], "help": ["Use the urgent-help link for urgent symptoms. This pathway does not assess your symptoms.", "استخدمي رابط المساعدة العاجلة للأعراض العاجلة. هذا المسار لا يقيّم أعراضك."], "url": "https://www.nhs.uk/pregnancy/trying-for-a-baby/trying-to-get-pregnant/", "understand": ["Make a list of prescriptions, non-prescription medicines and supplements. Arrange a pre-pregnancy review for long-term conditions or previous pregnancy complications. Ask about vaccinations, screening and suitable folic acid. Do not stop prescribed treatment yourself. Support with smoking, alcohol, nutrition and mental wellbeing belongs in preparation too.", "اكتبي قائمة الوصفات والأدوية دون وصفة والمكملات. رتّبي مراجعة قبل الحمل للأمراض المزمنة أو مضاعفات حمل سابقة. اسألي عن اللقاحات والتحري وحمض الفوليك المناسب. لا توقفي العلاج الموصوف بنفسك. يشمل الاستعداد دعم الإقلاع عن التدخين والكحول والتغذية والصحة النفسية."], "assessment": ["Request assessment after a year of trying without pregnancy, or earlier when age, irregular cycles, a known condition or previous treatment may affect fertility. Do not assume the cause lies with one partner. Local eligibility, funding and referral arrangements differ; ask the service what applies to your situation.", "اطلبي التقييم بعد سنة من المحاولة دون حمل، أو أبكر إذا كان العمر أو عدم انتظام الدورة أو مرض معروف أو علاج سابق قد يؤثر في الخصوبة. لا تفترضي أن السبب لدى شريك واحد. تختلف شروط الخدمة والتمويل والإحالة محليًا؛ اسألي عمّا ينطبق على حالتك."], "options": ["Assessment may include a cycle and pregnancy history, ovulation-related blood tests, ultrasound, tests of the fallopian tubes and semen analysis. Not everyone needs every test. Ask what each result changes. Treatment depends on the cause and preferences; an assessment does not automatically mean IVF. Ask about alternatives, costs and realistic expectations before committing.", "قد يشمل التقييم تاريخ الدورة والحمل وتحاليل مرتبطة بالإباضة والتصوير وفحص الأنابيب وتحليل السائل المنوي. لا يحتاج الجميع لكل الفحوص. اسألي كيف تغيّر النتيجة الخطة. يعتمد العلاج على السبب والتفضيلات ولا يعني التقييم تلقائيًا أطفال الأنابيب. اسألي عن البدائل والتكلفة والتوقعات الواقعية قبل القرار."], "faq": [["What if I still need help?", "ماذا إن احتجت مساعدة إضافية؟", "Arrange follow-up and ask who is responsible for reviewing results and next steps.", "رتّبي متابعة واسألي من يراجع النتائج والخطوات التالية."]], "questions": [["What should improve, and when should I return if it does not?", "ما التحسن المتوقع ومتى أعود إن لم يحدث؟"], ["Who will explain my results and arrange the next step?", "من يشرح نتائجي ويرتّب الخطوة التالية؟"]]}, {"id": "pregnancy-care", "title": ["Pregnancy: from a positive test to your care plan", "الحمل: من الاختبار الإيجابي إلى خطة المتابعة"], "chapters": ["expecting", "birth"], "related": ["maternal-warning", "pregnancy-conditions", "labour", "ectopic", "pregnancy-loss"], "sources": [["NHS: antenatal care", "https://www.nhs.uk/pregnancy/your-pregnancy-care/your-antenatal-care-and-appointments/"], ["CDC: maternal warning signs", "https://www.cdc.gov/hearher/maternal-warning-signs/index.html"], ["ACOG: pregnancy dating", "https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2017/05/methods-for-estimating-the-due-date"]], "sections": [{"title": ["Arrange care early", "رتّبي الرعاية مبكرًا"], "text": ["Contact maternity care when you know you are pregnant. Bring your period or embryo-transfer dates, medicine list and previous pregnancy history. Ask who to contact between visits. The dates calculator estimates timing; it cannot confirm that a pregnancy is developing normally or is in the uterus.", "تواصلي مع رعاية الحمل عند معرفة الحمل. أحضري تاريخ الدورة أو نقل الأجنة وقائمة الأدوية وتاريخ الحمل السابق. اسألي بمن تتواصلين بين الزيارات. تقدّر الحاسبة التوقيت لكنها لا تؤكد التطور الطبيعي للحمل أو وجوده داخل الرحم."]}, {"title": ["What scans and screening answer", "ماذا توضّح الأشعة والتحري؟"], "text": ["In the NHS reference pathway, an early scan at 11–14 weeks helps date the pregnancy and identify multiples; a later scan at 18–21 weeks examines development. Screening estimates the chance of certain conditions and is a choice. Ask what a result means and whether further testing is offered. Your local timetable may differ.", "في المسار المرجعي البريطاني يساعد فحص ١١–١٤ أسبوعًا في تحديد العمر والتعدد، ويفحص تصوير ١٨–٢١ أسبوعًا التطور. يقدّر التحري احتمال بعض الحالات وهو اختياري. اسألي عن معنى النتيجة والحاجة لفحوص إضافية. قد يختلف جدول بلدك."]}, {"title": ["Routine care or additional monitoring?", "متابعة اعتيادية أم إضافية؟"], "text": ["Visits may include blood pressure, urine checks, blood tests and discussion of growth and wellbeing. Existing conditions, pregnancy history and new findings can change the plan. A low-risk label is not a guarantee; extra monitoring does not mean a complication is certain. Record the plan agreed with your team, not a risk category chosen by an app.", "قد تشمل الزيارات الضغط والبول وتحاليل الدم ومناقشة النمو والصحة. قد تغيّر الأمراض السابقة وتاريخ الحمل والنتائج الجديدة الخطة. وصف «منخفض الخطورة» ليس ضمانًا، والمتابعة الإضافية لا تعني حتمية المضاعفات. سجّلي الخطة المتفق عليها مع الفريق وليس تصنيف تطبيق."]}, {"title": ["Keep estimates separate from appointments", "افصلي التقدير عن الموعد"], "text": ["A due date is an estimate. A clinician may revise it using dating information; use the confirmed date when available. A planned induction or caesarean date is a separate appointment. In My plan, record the actual booked visit. If pregnancy has ended, archive it to stop the pregnancy counter and choose the support you want next.", "موعد الولادة تقدير وقد يعدّله المختص وفق معلومات تحديد العمر؛ استخدمي التاريخ المؤكد عند توفره. موعد التحريض أو القيصرية موعد منفصل. سجّلي الموعد المحجوز في خطتي. إذا انتهى الحمل فأرشفيه لإيقاف العداد واختاري الدعم المناسب لاحقًا."]}, {"title": ["When waiting is not appropriate", "متى لا ينبغي الانتظار؟"], "text": ["Use the urgent-help list below for concerning symptoms. Do not let a reassuring calculator, previous scan or future appointment delay care. Tell the care team you are pregnant or were pregnant within the last year. If your maternity service cannot be reached and symptoms are urgent, seek emergency care.", "استخدمي قائمة المساعدة العاجلة أدناه للأعراض المقلقة. لا تجعلي حاسبة مطمئنة أو تصويرًا سابقًا أو موعدًا لاحقًا يؤخر الرعاية. أخبري الفريق بالحمل أو بحمل خلال السنة الماضية. إذا تعذر التواصل مع قسم الولادة وكانت الأعراض عاجلة، اطلبي الطوارئ."]}], "body": ["A step-by-step guide to understanding your concern, preparing for care and following up.", "دليل خطوة بخطوة لفهم مخاوفك والاستعداد للرعاية والمتابعة."], "track": ["Write down your priority, what you have already tried and the questions you want answered.", "دوّني أولويتك وما جرّبتِه والأسئلة التي تريدين الإجابة عنها."], "help": ["Use the urgent-help link for urgent symptoms. This pathway does not assess your symptoms.", "استخدمي رابط المساعدة العاجلة للأعراض العاجلة. هذا المسار لا يقيّم أعراضك."], "url": "https://www.nhs.uk/pregnancy/your-pregnancy-care/your-antenatal-care-and-appointments/", "understand": ["Contact maternity care when you know you are pregnant. Bring your period or embryo-transfer dates, medicine list and previous pregnancy history. Ask who to contact between visits. The dates calculator estimates timing; it cannot confirm that a pregnancy is developing normally or is in the uterus.", "تواصلي مع رعاية الحمل عند معرفة الحمل. أحضري تاريخ الدورة أو نقل الأجنة وقائمة الأدوية وتاريخ الحمل السابق. اسألي بمن تتواصلين بين الزيارات. تقدّر الحاسبة التوقيت لكنها لا تؤكد التطور الطبيعي للحمل أو وجوده داخل الرحم."], "assessment": ["Visits may include blood pressure, urine checks, blood tests and discussion of growth and wellbeing. Existing conditions, pregnancy history and new findings can change the plan. A low-risk label is not a guarantee; extra monitoring does not mean a complication is certain. Record the plan agreed with your team, not a risk category chosen by an app.", "قد تشمل الزيارات الضغط والبول وتحاليل الدم ومناقشة النمو والصحة. قد تغيّر الأمراض السابقة وتاريخ الحمل والنتائج الجديدة الخطة. وصف «منخفض الخطورة» ليس ضمانًا، والمتابعة الإضافية لا تعني حتمية المضاعفات. سجّلي الخطة المتفق عليها مع الفريق وليس تصنيف تطبيق."], "options": ["A due date is an estimate. A clinician may revise it using dating information; use the confirmed date when available. A planned induction or caesarean date is a separate appointment. In My plan, record the actual booked visit. If pregnancy has ended, archive it to stop the pregnancy counter and choose the support you want next.", "موعد الولادة تقدير وقد يعدّله المختص وفق معلومات تحديد العمر؛ استخدمي التاريخ المؤكد عند توفره. موعد التحريض أو القيصرية موعد منفصل. سجّلي الموعد المحجوز في خطتي. إذا انتهى الحمل فأرشفيه لإيقاف العداد واختاري الدعم المناسب لاحقًا."], "faq": [["What if I still need help?", "ماذا إن احتجت مساعدة إضافية؟", "Arrange follow-up and ask who is responsible for reviewing results and next steps.", "رتّبي متابعة واسألي من يراجع النتائج والخطوات التالية."]], "questions": [["What should improve, and when should I return if it does not?", "ما التحسن المتوقع ومتى أعود إن لم يحدث؟"], ["Who will explain my results and arrange the next step?", "من يشرح نتائجي ويرتّب الخطوة التالية؟"]]}, {"id": "recovery-care", "title": ["After birth: recovery, feeding & emotional health", "بعد الولادة: التعافي والتغذية والصحة النفسية"], "chapters": ["after"], "related": ["maternal-warning", "feeding-problems", "postnatal-mood", "pelvic-floor", "pain-sex"], "sources": [["NHS: body after birth", "https://www.nhs.uk/pregnancy/labour-and-birth/your-body/"], ["NHS: postnatal depression", "https://www.nhs.uk/mental-health/conditions/postnatal-depression/"], ["NHS: feeding problems", "https://www.nhs.uk/baby/breastfeeding-and-bottle-feeding/breastfeeding-problems/common-problems/"]], "sections": [{"title": ["Recovery is more than a countdown", "التعافي أكثر من عدّ الأيام"], "text": ["Bleeding, soreness, bowel changes and leaking urine can occur after birth. Recovery differs after vaginal and caesarean birth. Note whether symptoms are improving or worsening and follow your discharge instructions. A weeks-since-birth calculator does not decide whether recovery is normal or whether you are ready for exercise or sex.", "قد يحدث نزف وألم وتغيّر في الأمعاء وتسرب بول بعد الولادة. يختلف التعافي بعد الولادة المهبلية والقيصرية. راقبي تحسن الأعراض أو تفاقمها واتبعي تعليمات الخروج. لا تحدد حاسبة الأسابيع سلامة التعافي أو الاستعداد للرياضة أو الجماع."]}, {"title": ["Make support practical", "اجعلي الدعم عمليًا"], "text": ["Arrange help with meals, rest and daily tasks. Ask your team about wound care, pain relief and pelvic-floor exercises appropriate to you. Ongoing leaking, pelvic heaviness or pain deserves follow-up. Keep the discharge contact and planned review date accessible. Contact the team earlier if you are worried; a scheduled review is not a reason to wait.", "رتّبي المساعدة في الطعام والراحة والمهام اليومية. اسألي الفريق عن العناية بالجرح والمسكنات وتمارين الحوض الملائمة. يستحق استمرار التسرب أو ثقل الحوض أو الألم المتابعة. احتفظي بجهة التواصل وموعد المراجعة. تواصلي أبكر عند القلق؛ الموعد المحدد لا يبرر الانتظار."]}, {"title": ["Feeding should include your wellbeing", "التغذية تشمل صحتك أيضًا"], "text": ["If breastfeeding is painful, ask someone trained in feeding support to observe a feed and check attachment. Sore nipples, engorgement and mastitis need different approaches. Do not assume that enduring pain is part of successful feeding. Bring concerns about milk supply or your baby’s feeding to the care team. You can ask for support with mixed or formula feeding too.", "إذا كانت الرضاعة مؤلمة فاطلبي من مختص ملاحظة رضعة وتقييم الالتقام. تختلف معالجة ألم الحلمة والاحتقان والتهاب الثدي. ليس تحمّل الألم شرطًا لنجاح الرضاعة. ناقشي كمية الحليب وتغذية الطفل مع الفريق. يمكنك أيضًا طلب دعم التغذية المختلطة أو الصناعية."]}, {"title": ["Mood symptoms deserve care", "أعراض المزاج تستحق الرعاية"], "text": ["Brief tearfulness may settle, but persistent or worsening low mood, anxiety, loss of enjoyment or difficulty coping needs help. You do not have to wait until symptoms become severe. Treatment may include talking therapy, medicines and practical support. Tell the prescriber if breastfeeding. Immediate danger to yourself or your baby requires urgent help.", "قد يزول البكاء العابر، لكن استمرار أو تفاقم الحزن والقلق وفقدان المتعة وصعوبة التكيف يحتاج مساعدة. لا تنتظري شدة الأعراض. قد يشمل العلاج جلسات نفسية وأدوية ودعمًا عمليًا. أخبري الواصف بالرضاعة. الخطر الفوري عليك أو على طفلك يستدعي مساعدة عاجلة."]}, {"title": ["Plan the follow-up you actually need", "خطّطي للمتابعة التي تحتاجينها"], "text": ["List your top concerns before the visit: pain, bleeding, feeding, mood, continence or intimacy. Ask which clinician will handle each issue and when you should hear back. Discuss contraception if relevant. The plan can include separate appointments; you do not have to solve every concern in one short visit.", "رتّبي أهم المخاوف قبل الموعد: الألم والنزف والتغذية والمزاج والتحكم بالبول أو العلاقة. اسألي من يتابع كل مشكلة ومتى يصلك الرد. ناقشي منع الحمل إن كان مناسبًا. قد تشمل الخطة مواعيد منفصلة؛ لا يلزم حل كل المخاوف في زيارة قصيرة."]}], "body": ["A step-by-step guide to understanding your concern, preparing for care and following up.", "دليل خطوة بخطوة لفهم مخاوفك والاستعداد للرعاية والمتابعة."], "track": ["Write down your priority, what you have already tried and the questions you want answered.", "دوّني أولويتك وما جرّبتِه والأسئلة التي تريدين الإجابة عنها."], "help": ["Use the urgent-help link for urgent symptoms. This pathway does not assess your symptoms.", "استخدمي رابط المساعدة العاجلة للأعراض العاجلة. هذا المسار لا يقيّم أعراضك."], "url": "https://www.nhs.uk/pregnancy/labour-and-birth/your-body/", "understand": ["Bleeding, soreness, bowel changes and leaking urine can occur after birth. Recovery differs after vaginal and caesarean birth. Note whether symptoms are improving or worsening and follow your discharge instructions. A weeks-since-birth calculator does not decide whether recovery is normal or whether you are ready for exercise or sex.", "قد يحدث نزف وألم وتغيّر في الأمعاء وتسرب بول بعد الولادة. يختلف التعافي بعد الولادة المهبلية والقيصرية. راقبي تحسن الأعراض أو تفاقمها واتبعي تعليمات الخروج. لا تحدد حاسبة الأسابيع سلامة التعافي أو الاستعداد للرياضة أو الجماع."], "assessment": ["If breastfeeding is painful, ask someone trained in feeding support to observe a feed and check attachment. Sore nipples, engorgement and mastitis need different approaches. Do not assume that enduring pain is part of successful feeding. Bring concerns about milk supply or your baby’s feeding to the care team. You can ask for support with mixed or formula feeding too.", "إذا كانت الرضاعة مؤلمة فاطلبي من مختص ملاحظة رضعة وتقييم الالتقام. تختلف معالجة ألم الحلمة والاحتقان والتهاب الثدي. ليس تحمّل الألم شرطًا لنجاح الرضاعة. ناقشي كمية الحليب وتغذية الطفل مع الفريق. يمكنك أيضًا طلب دعم التغذية المختلطة أو الصناعية."], "options": ["Brief tearfulness may settle, but persistent or worsening low mood, anxiety, loss of enjoyment or difficulty coping needs help. You do not have to wait until symptoms become severe. Treatment may include talking therapy, medicines and practical support. Tell the prescriber if breastfeeding. Immediate danger to yourself or your baby requires urgent help.", "قد يزول البكاء العابر، لكن استمرار أو تفاقم الحزن والقلق وفقدان المتعة وصعوبة التكيف يحتاج مساعدة. لا تنتظري شدة الأعراض. قد يشمل العلاج جلسات نفسية وأدوية ودعمًا عمليًا. أخبري الواصف بالرضاعة. الخطر الفوري عليك أو على طفلك يستدعي مساعدة عاجلة."], "faq": [["What if I still need help?", "ماذا إن احتجت مساعدة إضافية؟", "Arrange follow-up and ask who is responsible for reviewing results and next steps.", "رتّبي متابعة واسألي من يراجع النتائج والخطوات التالية."]], "questions": [["What should improve, and when should I return if it does not?", "ما التحسن المتوقع ومتى أعود إن لم يحدث؟"], ["Who will explain my results and arrange the next step?", "من يشرح نتائجي ويرتّب الخطوة التالية؟"]]}, {"id": "menopause-care", "title": ["Menopause: symptoms, choices & longer-term health", "انقطاع الطمث: الأعراض والخيارات والصحة لاحقًا"], "chapters": ["transition", "later"], "related": ["perimenopause", "menopause-treatment", "postmenopausal-bleeding", "bone-health", "pain-sex"], "sources": [["NHS: menopause", "https://www.nhs.uk/conditions/menopause-and-perimenopause/"], ["NHS: treatment", "https://www.nhs.uk/conditions/menopause-and-perimenopause/treatment/"], ["NHS: self-care", "https://www.nhs.uk/conditions/menopause-and-perimenopause/things-you-can-do/"], ["NHS: bleeding after menopause", "https://www.nhs.uk/conditions/post-menopausal-bleeding/"]], "sections": [{"title": ["Start with the symptoms affecting you", "ابدئي بالأعراض المؤثرة عليك"], "text": ["The transition can bring changing periods, hot flushes, sleep problems, mood changes and vaginal discomfort. Experiences differ. Write down what affects daily life rather than trying to fit a checklist. New symptoms should not automatically be attributed to menopause; bring unexpected changes to an assessment.", "قد تتغير الدورة وتظهر هبات ساخنة واضطرابات نوم ومزاج وانزعاج مهبلي. تختلف التجارب. دوّني ما يؤثر في حياتك بدل محاولة مطابقة قائمة. لا تنسبي كل عرض جديد تلقائيًا لانقطاع الطمث؛ ناقشي التغيرات غير المتوقعة عند التقييم."]}, {"title": ["Everyday measures you can try", "خطوات يومية يمكنك تجربتها"], "text": ["A regular sleep routine, a cooler bedroom and layers of light clothing can help comfort. Notice whether particular drinks or foods trigger flushes. Regular activity, including weight-bearing and resistance exercise suited to your ability, supports longer-term health. Vaginal moisturisers or water-based lubricant may help dryness. Ask for help if discomfort persists.", "قد تساعد مواعيد النوم المنتظمة وغرفة أبرد وطبقات ملابس خفيفة. لاحظي محفزات الهبات من الطعام والشراب. يدعم النشاط المنتظم وتمارين تحميل الوزن والمقاومة الملائمة لقدرتك الصحة لاحقًا. قد تساعد مرطبات المهبل أو المزلقات المائية للجفاف. اطلبي المساعدة إذا استمر الانزعاج."]}, {"title": ["Understand treatment categories", "افهمي أنواع العلاج"], "text": ["HRT can treat symptoms, but the formulation and route need an individual discussion. Systemic oestrogen usually needs progestogen protection when the uterus is present. Local vaginal treatment addresses vaginal or urinary symptoms. Non-hormonal options and talking therapies may also help. Herbal products can interact with medicines and are not automatically safe.", "قد يعالج العلاج الهرموني الأعراض لكن النوع وطريقة الاستخدام يحتاجان مناقشة فردية. يحتاج الإستروجين الجهازي عادة حماية بالبروجستوجين عند وجود الرحم. يستهدف العلاج المهبلي الموضعي الأعراض المهبلية أو البولية. قد تفيد البدائل غير الهرمونية والعلاجات النفسية. قد تتداخل الأعشاب مع الأدوية وليست آمنة تلقائيًا."]}, {"title": ["Bleeding and contraception are separate questions", "النزف ومنع الحمل سؤالان منفصلان"], "text": ["Bleeding after menopause needs assessment even if it happens once or is only spotting. Do not use symptom treatment as a reason to ignore it. HRT is not contraception. If pregnancy prevention is relevant, ask when and how contraception can be stopped based on your circumstances.", "يحتاج النزف بعد انقطاع الطمث تقييمًا ولو حدث مرة أو كان نقاطًا. لا تتجاهليه بسبب استخدام علاج للأعراض. العلاج الهرموني ليس وسيلة لمنع الحمل. إذا كان منع الحمل مهمًا فاسألي عن توقيت وطريقة إيقاف الوسيلة حسب حالتك."]}, {"title": ["Agree a review, not just a prescription", "اتفقي على متابعة لا وصفة فقط"], "text": ["Choose the symptom you most want to improve. Ask how you will judge benefit, what side effects to report and when the treatment will be reviewed. Bring medicines and relevant personal or family history. You may revisit the choice if priorities or symptoms change. Bone health, sexual comfort and emotional wellbeing belong in the same conversation.", "حددي العرض الأهم للتحسين. اسألي كيف تقيسين الفائدة وما الأعراض الجانبية التي تبلغين عنها ومتى تراجعين العلاج. أحضري الأدوية والتاريخ الشخصي والعائلي المهم. يمكنك تعديل القرار عند تغير الأعراض أو الأولويات. تشمل المناقشة صحة العظام والراحة الجنسية والصحة النفسية."]}], "body": ["A step-by-step guide to understanding your concern, preparing for care and following up.", "دليل خطوة بخطوة لفهم مخاوفك والاستعداد للرعاية والمتابعة."], "track": ["Write down your priority, what you have already tried and the questions you want answered.", "دوّني أولويتك وما جرّبتِه والأسئلة التي تريدين الإجابة عنها."], "help": ["Use the urgent-help link for urgent symptoms. This pathway does not assess your symptoms.", "استخدمي رابط المساعدة العاجلة للأعراض العاجلة. هذا المسار لا يقيّم أعراضك."], "url": "https://www.nhs.uk/conditions/menopause-and-perimenopause/", "understand": ["The transition can bring changing periods, hot flushes, sleep problems, mood changes and vaginal discomfort. Experiences differ. Write down what affects daily life rather than trying to fit a checklist. New symptoms should not automatically be attributed to menopause; bring unexpected changes to an assessment.", "قد تتغير الدورة وتظهر هبات ساخنة واضطرابات نوم ومزاج وانزعاج مهبلي. تختلف التجارب. دوّني ما يؤثر في حياتك بدل محاولة مطابقة قائمة. لا تنسبي كل عرض جديد تلقائيًا لانقطاع الطمث؛ ناقشي التغيرات غير المتوقعة عند التقييم."], "assessment": ["HRT can treat symptoms, but the formulation and route need an individual discussion. Systemic oestrogen usually needs progestogen protection when the uterus is present. Local vaginal treatment addresses vaginal or urinary symptoms. Non-hormonal options and talking therapies may also help. Herbal products can interact with medicines and are not automatically safe.", "قد يعالج العلاج الهرموني الأعراض لكن النوع وطريقة الاستخدام يحتاجان مناقشة فردية. يحتاج الإستروجين الجهازي عادة حماية بالبروجستوجين عند وجود الرحم. يستهدف العلاج المهبلي الموضعي الأعراض المهبلية أو البولية. قد تفيد البدائل غير الهرمونية والعلاجات النفسية. قد تتداخل الأعشاب مع الأدوية وليست آمنة تلقائيًا."], "options": ["Bleeding after menopause needs assessment even if it happens once or is only spotting. Do not use symptom treatment as a reason to ignore it. HRT is not contraception. If pregnancy prevention is relevant, ask when and how contraception can be stopped based on your circumstances.", "يحتاج النزف بعد انقطاع الطمث تقييمًا ولو حدث مرة أو كان نقاطًا. لا تتجاهليه بسبب استخدام علاج للأعراض. العلاج الهرموني ليس وسيلة لمنع الحمل. إذا كان منع الحمل مهمًا فاسألي عن توقيت وطريقة إيقاف الوسيلة حسب حالتك."], "faq": [["What if I still need help?", "ماذا إن احتجت مساعدة إضافية؟", "Arrange follow-up and ask who is responsible for reviewing results and next steps.", "رتّبي متابعة واسألي من يراجع النتائج والخطوات التالية."]], "questions": [["What should improve, and when should I return if it does not?", "ما التحسن المتوقع ومتى أعود إن لم يحدث؟"], ["Who will explain my results and arrange the next step?", "من يشرح نتائجي ويرتّب الخطوة التالية؟"]]}, {"id": "pregnancy-options", "title": ["An unexpected pregnancy: understanding your options", "حمل غير متوقع: فهم الخيارات"], "body": ["You can seek non-judgmental information when a pregnancy is unexpected or unwanted.", "يمكنك طلب معلومات دون أحكام عندما يكون الحمل غير متوقع أو غير مرغوب فيه."], "help": ["Severe pain, fainting or heavy bleeding needs urgent assessment, regardless of your decision.", "الألم الشديد أو الإغماء أو النزف الغزير يحتاج تقييمًا عاجلًا مهما كان قرارك."], "understand": ["You may want to discuss continuing the pregnancy and parenting, support arrangements, or abortion. Availability, time limits and legal requirements differ by location. This app has not verified a local access route.", "قد ترغبين بمناقشة استمرار الحمل والتربية أو ترتيبات الدعم أو الإجهاض. تختلف الإتاحة والحدود الزمنية والمتطلبات القانونية حسب المكان. لم يتحقق التطبيق من مسار وصول محلي."], "assessment": ["A qualified service can confirm pregnancy details and discuss health, gestation and preferences. Ask about confidentiality before disclosing information, especially when you are under 18 or someone is controlling your choices.", "يمكن لخدمة مؤهلة تأكيد تفاصيل الحمل ومناقشة الصحة وعمر الحمل والتفضيلات. اسألي عن السرية قبل الإفصاح، خصوصًا إذا كنت دون ١٨ عامًا أو كان شخص يتحكم باختياراتك."], "options": ["Abortion care may involve medicines or a procedure, depending on the situation and service. Ask how follow-up works and who to contact if unwell. This guide does not provide a regimen or certify a provider. Do not let pressure from another person replace your informed choice.", "قد تشمل رعاية الإجهاض أدوية أو إجراءً بحسب الحالة والخدمة. اسألي عن المتابعة وجهة التواصل عند التعب. لا يقدم الدليل نظام جرعات أو اعتمادًا لمقدم خدمة. لا تجعلي ضغط الآخرين يحل محل اختيارك المستنير."], "questions": [["What are my available options and how soon should I be seen?", "ما الخيارات المتاحة ومتى ينبغي مراجعتي؟"]], "related": ["ectopic", "pregnancy-loss", "safety-support"], "chapters": ["sexual", "expecting"], "sources": [["NHS: abortion information (UK)", "https://www.nhs.uk/tests-and-treatments/abortion/"]], "url": "https://www.nhs.uk/tests-and-treatments/abortion/", "track": ["Bring your main question and any previous results you want to discuss. Share sensitive details only where you feel safe.", "أحضري سؤالك الأساسي والنتائج السابقة التي ترغبين بمناقشتها. شاركي التفاصيل الحساسة فقط حيث تشعرين بالأمان."], "faq": [["Does this guide decide my treatment?", "هل يحدد هذا الدليل علاجي؟", "No. It helps you prepare for a qualified service and understand what to ask.", "لا. يساعدك على الاستعداد لخدمة مؤهلة ومعرفة ما تسألين عنه."]]}, {"id": "safety-support", "title": ["Consent, coercion & getting support", "الموافقة والإكراه وطلب الدعم"], "body": ["Your safety and your choices matter. This page does not require you to record what happened.", "سلامتك واختياراتك مهمتان. لا تحتاجين تسجيل ما حدث في هذه الصفحة."], "help": ["If you are in immediate danger, seek emergency assistance or move to a safer place if you can.", "إذا كنت في خطر فوري فاطلبي مساعدة الطوارئ أو انتقلي لمكان أكثر أمانًا إن استطعت."], "understand": ["Sexual contact requires consent. Pressure, threats or forced contact are not your fault. Support may include medical care, emotional support and practical safety planning. You can seek healthcare even if you are unsure about reporting to police; local procedures differ.", "يتطلب التواصل الجنسي موافقة. الضغط أو التهديد أو التواصل القسري ليس خطأك. قد يشمل الدعم الرعاية الطبية والنفسية وخطة السلامة. يمكنك طلب الرعاية حتى مع التردد في إبلاغ الشرطة؛ تختلف الإجراءات محليًا."], "assessment": ["After a recent assault, prompt specialist care can address injuries and time-sensitive pregnancy and infection prevention. Ask what each examination involves and about confidentiality and safeguarding duties. You can request a support person or an interpreter.", "بعد اعتداء حديث يمكن للرعاية المتخصصة السريعة معالجة الإصابات والوقاية المرتبطة بالوقت من الحمل والعدوى. اسألي عن كل فحص والسرية وواجبات الحماية. يمكنك طلب شخص داعم أو مترجم."], "options": ["If your device is monitored, consider a safer device or trusted support contact. Leaving this page does not erase browser history or saved data. Avoid saving sensitive notes here on a shared device. This prototype has no confidential messaging or live support service.", "إذا كان جهازك مراقبًا ففكري بجهاز أكثر أمانًا أو جهة دعم موثوقة. مغادرة الصفحة لا تمسح السجل أو البيانات. تجنبي حفظ ملاحظات حساسة على جهاز مشترك. لا يوفر النموذج مراسلة سرية أو دعمًا مباشرًا."], "questions": [["What are your confidentiality rules and my choices during examination?", "ما قواعد السرية وما خياراتي أثناء الفحص؟"]], "related": ["examination", "sti", "emergency-contraception"], "chapters": ["sexual", "growing"], "sources": [["NHS: care after sexual assault", "https://www.nhs.uk/live-well/sexual-health/help-after-rape-and-sexual-assault/"], ["WHO: violence against women", "https://www.who.int/news-room/fact-sheets/detail/violence-against-women"]], "url": "https://www.nhs.uk/live-well/sexual-health/help-after-rape-and-sexual-assault/", "track": ["Bring your main question and any previous results you want to discuss. Share sensitive details only where you feel safe.", "أحضري سؤالك الأساسي والنتائج السابقة التي ترغبين بمناقشتها. شاركي التفاصيل الحساسة فقط حيث تشعرين بالأمان."], "faq": [["Does this guide decide my treatment?", "هل يحدد هذا الدليل علاجي؟", "No. It helps you prepare for a qualified service and understand what to ask.", "لا. يساعدك على الاستعداد لخدمة مؤهلة ومعرفة ما تسألين عنه."]]}, {"id": "fertility-treatment", "title": ["Fertility treatment: decisions before IVF", "علاج الخصوبة: قرارات قبل أطفال الأنابيب"], "body": ["Treatment should follow an assessment of the situation and your priorities.", "ينبغي أن يتبع العلاج تقييم الحالة وأولوياتك."], "help": ["During treatment, report significant pain or bloating promptly. Breathing difficulty, chest pain or collapse needs emergency care.", "أبلغي سريعًا عن ألم أو انتفاخ ملحوظ أثناء العلاج. صعوبة التنفس أو ألم الصدر أو الانهيار يستدعي الطوارئ."], "understand": ["IVF fertilises eggs in a laboratory and transfers an embryo to the uterus. Other treatments may be appropriate depending on the cause. IVF does not guarantee a baby; ask for realistic expectations for your situation.", "يُخصّب أطفال الأنابيب البويضات بالمختبر ثم يُنقل جنين للرحم. قد تناسب علاجات أخرى بحسب السبب. لا يضمن العلاج إنجاب طفل؛ اسألي عن توقعات واقعية لحالتك."], "assessment": ["Discuss investigations, medicine monitoring, egg collection, embryo transfer and storage before starting. Ask about the risk of ovarian hyperstimulation and multiple pregnancy. Understand consent documents and what is included in the quoted cost.", "ناقشي الفحوص ومراقبة الأدوية وسحب البويضات ونقل الأجنة وتخزينها قبل البدء. اسألي عن فرط تنبيه المبيض والحمل المتعدد. افهمي نماذج الموافقة وما تشمله التكلفة."], "options": ["Ask what happens after an unsuccessful cycle, when to test, and how to access emotional support. Follow the treating clinic’s dosing and monitoring plan; this app does not provide fertility-treatment protocols.", "اسألي عما يلي الدورة غير الناجحة وموعد اختبار الحمل والدعم النفسي. اتبعي جرعات وخطة مراقبة العيادة؛ لا يقدم التطبيق بروتوكولات علاج الخصوبة."], "questions": [["What are the alternatives, risks and total expected costs?", "ما البدائل والمخاطر والتكلفة الإجمالية المتوقعة؟"]], "related": ["fertility-assessment", "prepare-care"], "chapters": ["planning"], "sources": [["NHS: IVF", "https://www.nhs.uk/tests-and-treatments/ivf/"]], "url": "https://www.nhs.uk/tests-and-treatments/ivf/", "track": ["Bring your main question and any previous results you want to discuss. Share sensitive details only where you feel safe.", "أحضري سؤالك الأساسي والنتائج السابقة التي ترغبين بمناقشتها. شاركي التفاصيل الحساسة فقط حيث تشعرين بالأمان."], "faq": [["Does this guide decide my treatment?", "هل يحدد هذا الدليل علاجي؟", "No. It helps you prepare for a qualified service and understand what to ask.", "لا. يساعدك على الاستعداد لخدمة مؤهلة ومعرفة ما تسألين عنه."]]}, {"id": "pregnancy-complications", "title": ["Blood pressure & diabetes in pregnancy", "ضغط الدم والسكري أثناء الحمل"], "body": ["These conditions need a care plan, not a risk score from this app.", "تحتاج هذه الحالات خطة رعاية وليس درجة خطورة من التطبيق."], "help": ["Use the urgent symptoms below. A previous normal check does not exclude a new complication.", "راجعي الأعراض العاجلة أدناه. لا يستبعد فحص طبيعي سابق مضاعفة جديدة."], "understand": ["Pre-eclampsia is a pregnancy-related condition associated with high blood pressure and can be serious. Gestational diabetes is high blood sugar developing in pregnancy. Either may be found during planned checks rather than because you feel unwell.", "مقدمات الارتعاج حالة مرتبطة بالحمل وارتفاع الضغط وقد تكون خطرة. سكري الحمل ارتفاع السكر الذي يتطور أثناء الحمل. قد يُكتشف أي منهما بالفحوص المخططة دون الشعور بالتعب."], "assessment": ["Assessment may include blood pressure, urine and blood tests and monitoring of the baby. Diabetes testing and glucose monitoring follow your team’s plan. A home reading needs interpretation in context; do not change treatment using this app.", "قد يشمل التقييم الضغط والبول والدم ومراقبة الجنين. يتبع فحص السكري ومراقبة السكر خطة الفريق. تحتاج القراءة المنزلية تفسيرًا حسب الحالة؛ لا تغيري العلاج باستخدام التطبيق."], "options": ["Care may involve extra appointments and medicines. Diabetes care also includes tailored eating and activity advice. Your team decides whether birth timing needs to change. Ask which readings or symptoms require contact and what follow-up is needed after birth.", "قد تشمل الرعاية مواعيد إضافية وأدوية. يشمل علاج السكري إرشادات طعام ونشاط ملائمة. يحدد الفريق الحاجة لتغيير توقيت الولادة. اسألي عن القراءات والأعراض التي تستدعي الاتصال والمتابعة بعد الولادة."], "questions": [["What is my monitoring plan and who reviews my readings?", "ما خطة المراقبة ومن يراجع قراءاتي؟"]], "related": ["pregnancy-care", "maternal-warning", "pregnancy-conditions"], "chapters": ["expecting"], "sources": [["NHS: pre-eclampsia", "https://www.nhs.uk/conditions/pre-eclampsia/"], ["NHS: gestational diabetes", "https://www.nhs.uk/conditions/gestational-diabetes/"]], "url": "https://www.nhs.uk/conditions/pre-eclampsia/", "track": ["Bring your main question and any previous results you want to discuss. Share sensitive details only where you feel safe.", "أحضري سؤالك الأساسي والنتائج السابقة التي ترغبين بمناقشتها. شاركي التفاصيل الحساسة فقط حيث تشعرين بالأمان."], "faq": [["Does this guide decide my treatment?", "هل يحدد هذا الدليل علاجي؟", "No. It helps you prepare for a qualified service and understand what to ask.", "لا. يساعدك على الاستعداد لخدمة مؤهلة ومعرفة ما تسألين عنه."]]}, {"id": "cancer-support", "title": ["Facing a cancer investigation or diagnosis", "مواجهة فحوص السرطان أو تشخيصه"], "body": ["This is a preparation guide, not a cancer treatment recommendation.", "دليل للاستعداد وليس توصية بعلاج السرطان."], "help": ["If you are already receiving treatment, use your oncology team’s urgent-contact instructions. Severe symptoms need urgent care.", "إذا كنت تتلقين العلاج فاتبعي تعليمات التواصل العاجل لفريق الأورام. الأعراض الشديدة تحتاج رعاية عاجلة."], "understand": ["An investigation is not the same as a confirmed diagnosis. Ask what is known, what remains uncertain and which result will clarify the next step. Cancer care differs by organ, type and stage.", "الفحوص لا تعني تشخيصًا مؤكدًا. اسألي عما هو معروف وغير مؤكد وعن النتيجة التي توضح الخطوة التالية. تختلف الرعاية باختلاف العضو والنوع والمرحلة."], "assessment": ["For example, ovarian cancer treatment may involve surgery and chemotherapy; some people receive targeted medicines. A specialist team considers the diagnosis and personal situation. This example must not be applied to other cancers or used to choose your treatment.", "مثلًا قد يشمل علاج سرطان المبيض الجراحة والكيماوي وقد يتلقى بعض الأشخاص أدوية موجهة. ينظر الفريق المتخصص للتشخيص والحالة الشخصية. لا يُطبّق المثال على السرطانات الأخرى ولا يُستخدم لاختيار علاجك."], "options": ["Take a trusted person if you wish and request a written plan. Ask about treatment goals, side effects, fertility, sexual health and symptom support. Clarify who coordinates care and when you should receive results. You may ask about a second opinion.", "اصطحبي شخصًا موثوقًا إن رغبت واطلبي خطة مكتوبة. اسألي عن هدف العلاج وآثاره والخصوبة والصحة الجنسية ودعم الأعراض. حددي من ينسق الرعاية وموعد النتائج. يمكنك السؤال عن رأي ثانٍ."], "questions": [["What is confirmed, and what are the goals and alternatives of treatment?", "ما المؤكد وما أهداف العلاج وبدائله؟"]], "related": ["bloating", "breast", "screening", "postmenopausal-bleeding"], "chapters": ["prevention", "body"], "sources": [["NHS: ovarian cancer treatment", "https://www.nhs.uk/conditions/ovarian-cancer/treatment/"]], "url": "https://www.nhs.uk/conditions/ovarian-cancer/treatment/", "track": ["Bring your main question and any previous results you want to discuss. Share sensitive details only where you feel safe.", "أحضري سؤالك الأساسي والنتائج السابقة التي ترغبين بمناقشتها. شاركي التفاصيل الحساسة فقط حيث تشعرين بالأمان."], "faq": [["Does this guide decide my treatment?", "هل يحدد هذا الدليل علاجي؟", "No. It helps you prepare for a qualified service and understand what to ask.", "لا. يساعدك على الاستعداد لخدمة مؤهلة ومعرفة ما تسألين عنه."]]}];
